// LR専用: 画面シャター(破砕)演出
async function showLegendShatter() {
  // 第1波: 中央にヒビ
  play("se-crack");
  showCrack();
  stage.classList.add("shake");
  await sleep(280);
  if (checkSkip()) { stage.classList.remove("shake"); return; }
  // 第2波: 重ねヒビ + シャター背景
  play("se-crack");
  showCrack();
  const bg = document.createElement("div");
  bg.className = "fx-shatter on";
  stageVfx.appendChild(bg);
  setTimeout(() => bg.remove(), 1200);
  await sleep(260);
  if (checkSkip()) { stage.classList.remove("shake"); return; }
  // 第3波: 画面が4分割に砕け散る
  play("se-crack");
  for (let i = 1; i <= 4; i++) {
    const s = document.createElement("div");
    s.className = "fx-shard on s" + i;
    stageVfx.appendChild(s);
    setTimeout(() => s.remove(), 1100);
  }
  flash("hard");
  await sleep(500);
  stage.classList.remove("shake");
  // 破砕が収まり、ここから LR本命演出へ
}

