const REL_STYLE = {
  fellow:    { color: '#5fffaa', dash: 'none',     w: 2.5, directed: false },
  master:    { color: '#ffd84d', dash: 'none',     w: 2.5, directed: true  }, // a=師 → b=弟子
  blood:     { color: '#ff5faa', dash: 'none',     w: 2.5, directed: false },
  childhood: { color: '#c87dff', dash: 'none',     w: 2.5, directed: false },
  admire:    { color: '#7ea8ff', dash: '6,4',      w: 1.8, directed: true  }, // a=憧れる人 → b=憧れられる人
  rival:     { color: '#ff8855', dash: '2,3',      w: 2.0, directed: false },
  sister:    { color: '#ff9fd0', dash: 'none',     w: 2.0, directed: true  }, // a=姉 → b=妹分
};

function getCharByName(name) {
  for (const tier of ['LR','UR','SSR','SR','R']) {
    const c = POOL[tier].find(x => x.name === name);
    if (c) return { ...c, tier };
  }
  return null;
}

// 相関図 focus state — 派閥クリックで該当派閥の相関のみハイライト (野沢さん指示 2026-05-02)
let _relationsFocusFaction = null;
function setRelationsFocus(facId) {
  _relationsFocusFaction = (_relationsFocusFaction === facId) ? null : facId;
  _redrawRelationsCanvas();
}
function clearRelationsFocus() {
  _relationsFocusFaction = null;
  _redrawRelationsCanvas();
}
function _redrawRelationsCanvas() {
  const canvas = document.getElementById('relations-canvas');
  if (!canvas) return;
  // viewBox は scale 適用後の総空間 + 周囲バッファ (sahar 等 端の派閥が見切れない)
  const W = 2000 * REL_FACTION_SCALE, H = 1600 * REL_FACTION_SCALE;
  const PAD = 200;  // 派閥背景円半径 (175*1.25=219) + ラベル領域分のバッファ
  // focus 中: SVG viewBox 自体を派閥中心の縮小範囲に切替 → 自然に画面中央拡大表示
  let viewBoxAttr = `${-PAD} ${-PAD} ${W + PAD * 2} ${H + PAD * 2}`;
  if (_relationsFocusFaction) {
    const f = FACTIONS.find(ff => ff.id === _relationsFocusFaction);
    if (f) {
      const fp = _scaledFactionPos(f);
      const scale = 2.4;
      const focusW = W / scale, focusH = H / scale;
      const fx = Math.max(-PAD, Math.min(W + PAD - focusW, fp.x - focusW / 2));
      const fy = Math.max(-PAD, Math.min(H + PAD - focusH, fp.y - focusH / 2));
      viewBoxAttr = `${fx} ${fy} ${focusW} ${focusH}`;
    }
  }
  canvas.innerHTML = `<svg viewBox="${viewBoxAttr}" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet" class="relations-svg${_relationsFocusFaction ? ' focused' : ''}">
    <defs>${renderArrowMarkers()}</defs>
    ${renderFactionBg()}
    ${renderRelationLines()}
    ${renderFactionLabels()}
    ${renderCharNodes()}
  </svg>`;
  _bindRelationsClickHandlers(canvas);
  // focus 中は SVG が画面中央に派閥を表示するので canvas scroll は中央に reset
  if (_relationsFocusFaction) {
    const sw = canvas.scrollWidth, sh = canvas.scrollHeight;
    canvas.scrollTo({ left: (sw - canvas.clientWidth) / 2, top: (sh - canvas.clientHeight) / 2, behavior: 'smooth' });
  }
  // focus 表示用「全表示に戻る」 ボタン
  const banner = document.getElementById('relations-focus-banner');
  if (banner) {
    if (_relationsFocusFaction) {
      const f = FACTIONS.find(ff => ff.id === _relationsFocusFaction);
      banner.innerHTML = `<span>📍 ${f ? f.label : ''} に絞り込み中</span> <button type="button" onclick="clearRelationsFocus()">✕ 全表示に戻る</button>`;
      banner.hidden = false;
    } else {
      banner.hidden = true;
      banner.innerHTML = '';
    }
  }
}
function _bindRelationsClickHandlers(canvas) {
  // キャラタップ → 詳細
  canvas.querySelectorAll('[data-char-name]').forEach(el => {
    el.addEventListener('click', e => {
      if (relationsDragMoved) return;
      const name = el.dataset.charName;
      const c = getCharByName(name);
      if (c && isUnlocked(c)) {
        if (detailUnlockedList.length === 0) {
          detailUnlockedList = getAllCharactersWithTier().filter(x => isUnlocked(x));
        }
        showCharDetail(c);
      }
    });
  });
  // 派閥タップ (背景円 + ラベル) → focus 切替
  canvas.querySelectorAll('[data-faction-id]').forEach(el => {
    el.addEventListener('click', e => {
      if (relationsDragMoved) return;
      e.stopPropagation();
      setRelationsFocus(el.dataset.factionId);
    });
  });
}
window.clearRelationsFocus = clearRelationsFocus;

function openRelations() {
  // focus state リセット
  _relationsFocusFaction = null;
  const canvas = document.getElementById('relations-canvas');
  // banner エレメント (focus 中のみ表示) を準備
  let banner = document.getElementById('relations-focus-banner');
  if (!banner) {
    banner = document.createElement('div');
    banner.id = 'relations-focus-banner';
    banner.className = 'relations-focus-banner';
    banner.hidden = true;
    canvas.parentElement.insertBefore(banner, canvas);
  }
  _redrawRelationsCanvas();
  document.getElementById('relations').classList.add('active');

  // 初期位置: 中央寄せ
  setTimeout(() => {
    const sw = canvas.scrollWidth, sh = canvas.scrollHeight;
    canvas.scrollLeft = (sw - canvas.clientWidth) / 2;
    canvas.scrollTop = (sh - canvas.clientHeight) / 2;
  }, 0);

  bindRelationsPan(canvas);
  bindRelationsZoomWheel(canvas);
  // タブ初期化 (スマホはリストをデフォルト)
  setupRelationsTabs();
  const isMobile = window.matchMedia('(max-width: 720px)').matches;
  setRelationsMode(isMobile ? 'list' : 'graph');
  // 開く度に zoom はリセット (前回開いた zoom が残ると違和感)
  setRelationsZoom(1.0);
}

// 相関図 拡大縮小 (野沢さん指示 2026-05-03)
// CSS で svg width/height = 2200x1820 px。 _relationsZoom 倍率で動的に上書き
let _relationsZoom = 1.0;
const REL_ZOOM_MIN = 0.5, REL_ZOOM_MAX = 2.5, REL_ZOOM_STEP = 0.2;
const REL_SVG_BASE_W = 2200, REL_SVG_BASE_H = 1820;
function setRelationsZoom(z) {
  _relationsZoom = Math.max(REL_ZOOM_MIN, Math.min(REL_ZOOM_MAX, z));
  const svg = document.querySelector('.relations-canvas svg');
  if (svg) {
    svg.style.width  = (REL_SVG_BASE_W * _relationsZoom) + 'px';
    svg.style.height = (REL_SVG_BASE_H * _relationsZoom) + 'px';
  }
  const lvl = document.getElementById('rel-zoom-level');
  if (lvl) lvl.textContent = Math.round(_relationsZoom * 100) + '%';
}
function zoomRelationsIn()    { setRelationsZoom(_relationsZoom + REL_ZOOM_STEP); }
function zoomRelationsOut()   { setRelationsZoom(_relationsZoom - REL_ZOOM_STEP); }
function zoomRelationsReset() { setRelationsZoom(1.0); }
window.zoomRelationsIn = zoomRelationsIn;
window.zoomRelationsOut = zoomRelationsOut;
window.zoomRelationsReset = zoomRelationsReset;
let _relationsZoomWheelBound = false;
function bindRelationsZoomWheel(canvas) {
  if (_relationsZoomWheelBound) return;
  _relationsZoomWheelBound = true;
  // Ctrl/Cmd + ホイールで拡縮 (普通のスクロールと区別)、 タッチパッドのピンチも Ctrl 扱いされる
  canvas.addEventListener('wheel', e => {
    if (!e.ctrlKey && !e.metaKey) return;
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.1 : 0.1;
    setRelationsZoom(_relationsZoom + delta);
  }, { passive: false });
}

// #5 派閥別リスト表示
let _relationsTabsBound = false;
function setupRelationsTabs() {
  if (_relationsTabsBound) return;
  _relationsTabsBound = true;
  document.querySelectorAll('.rel-tab').forEach(b => {
    b.addEventListener('click', () => setRelationsMode(b.dataset.mode));
  });
}
function setRelationsMode(mode) {
  document.querySelectorAll('.rel-tab').forEach(b => {
    b.classList.toggle('active', b.dataset.mode === mode);
  });
  const canvas = document.getElementById('relations-canvas');
  const list = document.getElementById('relations-list');
  if (mode === 'list') {
    if (canvas) canvas.style.display = 'none';
    if (list) {
      list.style.display = '';
      renderRelationsList(list);
    }
  } else {
    if (canvas) canvas.style.display = '';
    if (list) list.style.display = 'none';
  }
}
function renderRelationsList(container) {
  // 派閥ごとにキャラをグループ化
  const byFaction = {}; // factionId -> [{name, char, relations}]
  for (const facId in {}) {} // init
  FACTIONS.forEach(f => { byFaction[f.id] = []; });
  // CHAR_FACTION から各キャラの派閥を引く
  for (const name in CHAR_FACTION) {
    const f = CHAR_FACTION[name].f;
    const c = getCharByName(name);
    if (!c) continue;
    if (!byFaction[f]) byFaction[f] = [];
    byFaction[f].push({ name, char: c });
  }
  // 各キャラの relations を集約 (未公開章のキャラは相手側にも出さない)
  function relsOf(charName) {
    const out = [];
    RELATIONS.forEach(r => {
      if (r.a === charName) {
        const oc = getCharByName(r.b);
        if (!_isCharReleased(oc)) return;
        out.push({ other: r.b, type: r.type, role: r.aRole || r.label || '', isMyEnd: 'a' });
      } else if (r.b === charName) {
        const oc = getCharByName(r.a);
        if (!_isCharReleased(oc)) return;
        out.push({ other: r.a, type: r.type, role: r.bRole || r.label || '', isMyEnd: 'b' });
      }
    });
    return out;
  }
  const TYPE_LABEL = {
    fellow: '🤝 戦友', master: '🎓 師弟', blood: '🩸 血縁',
    childhood: '🌸 幼馴染', admire: '✨ 憧憬', rival: '⚔ 好敵手', sister: '🌷 姉妹'
  };
  let html = '';
  FACTIONS.forEach(f => {
    const list = (byFaction[f.id] || []).filter(({ char }) => _isCharReleased(char));  // 未公開章キャラ非表示
    if (list.length === 0) return;
    html += `<section class="rel-faction" style="--fac-color:${f.color}">`;
    html += `<h3 class="rel-faction-head">${f.label} <span class="rel-faction-yomi">${f.yomi}</span> <span class="rel-faction-count">${list.length}名</span></h3>`;
    list.forEach(({ name, char }) => {
      const unlocked = isUnlocked(char);
      const rels = relsOf(name);
      html += `<div class="rel-char ${unlocked ? 'unlocked' : 'locked'}" data-char-name="${escapeHtml(name)}">`;
      html += `<div class="rel-char-head">`;
      html += `<span class="rel-char-tier rel-tier-${(char.tier || '').toLowerCase()}">${char.tier || ''}</span>`;
      html += `<span class="rel-char-name">${escapeHtml(name)}</span>`;
      if (char.title) html += `<span class="rel-char-title">${escapeHtml(char.title)}</span>`;
      html += `</div>`;
      if (rels.length === 0) {
        html += `<div class="rel-char-empty">— 単独 —</div>`;
      } else {
        html += `<ul class="rel-list">`;
        rels.forEach(r => {
          const otherChar = getCharByName(r.other);
          const tier = otherChar ? otherChar.tier : '?';
          html += `<li class="rel-item" data-other="${escapeHtml(r.other)}">`;
          html += `<span class="rel-type">${TYPE_LABEL[r.type] || r.type}</span>`;
          if (r.role) html += `<span class="rel-role">[${escapeHtml(r.role)}]</span>`;
          html += ` <span class="rel-other-tier rel-tier-${tier.toLowerCase()}">${tier}</span>`;
          html += ` <span class="rel-other">${escapeHtml(r.other)}</span>`;
          html += `</li>`;
        });
        html += `</ul>`;
      }
      html += `</div>`;
    });
    html += `</section>`;
  });
  container.innerHTML = html;
  // クリックで詳細表示 (解放済みのみ)
  container.querySelectorAll('.rel-char').forEach(el => {
    el.addEventListener('click', e => {
      // .rel-item の other クリックなら相手を開く、 head なら本人
      const itemEl = e.target.closest('.rel-item');
      const targetName = itemEl ? itemEl.dataset.other : el.dataset.charName;
      const c = getCharByName(targetName);
      if (c && isUnlocked(c)) {
        if (detailUnlockedList.length === 0) {
          detailUnlockedList = getAllCharactersWithTier().filter(x => isUnlocked(x));
        }
        showCharDetail(c);
      }
    });
  });
}

// ドラッグでパン
let relationsPanActive = false, relationsDragMoved = false;
let relPanStartX = 0, relPanStartY = 0, relPanScrollX = 0, relPanScrollY = 0;
let relationsPanBound = false;

function bindRelationsPan(canvas) {
  if (relationsPanBound) return;
  relationsPanBound = true;

  const start = (e) => {
    // キャラサムネ上で押した時もパン開始可 (移動量で判別)
    if (e.type === 'mousedown' && e.button !== 0) return;
    relationsPanActive = true;
    relationsDragMoved = false;
    const isTouch = e.type === 'touchstart';
    const x = isTouch ? e.touches[0].clientX : e.clientX;
    const y = isTouch ? e.touches[0].clientY : e.clientY;
    relPanStartX = x; relPanStartY = y;
    relPanScrollX = canvas.scrollLeft; relPanScrollY = canvas.scrollTop;
    canvas.style.cursor = 'grabbing';
  };
  const move = (e) => {
    if (!relationsPanActive) return;
    const isTouch = e.type === 'touchmove';
    const x = isTouch ? e.touches[0].clientX : e.clientX;
    const y = isTouch ? e.touches[0].clientY : e.clientY;
    const dx = x - relPanStartX, dy = y - relPanStartY;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) relationsDragMoved = true;
    if (relationsDragMoved) {
      canvas.scrollLeft = relPanScrollX - dx;
      canvas.scrollTop = relPanScrollY - dy;
      if (isTouch) e.preventDefault();
    }
  };
  const end = () => {
    relationsPanActive = false;
    canvas.style.cursor = 'grab';
    setTimeout(() => { relationsDragMoved = false; }, 30);
  };

  canvas.addEventListener('mousedown', start);
  document.addEventListener('mousemove', move);
  document.addEventListener('mouseup', end);
  canvas.addEventListener('touchstart', start, {passive: true});
  document.addEventListener('touchmove', move, {passive: false});
  document.addEventListener('touchend', end);
  canvas.style.cursor = 'grab';
}

function closeRelations() {
  document.getElementById('relations').classList.remove('active');
}

// 相関図の座標スケール (野沢さん指示 2026-05-03 「画面拡大じゃなく、 各派閥のキャラ間距離を実際に広げて」)
// FACTION_SCALE: 派閥配置 (派閥間距離) を倍率
// CHAR_SCALE:    派閥内キャラ間距離 (派閥中心からの相対座標 dx/dy) を倍率
// 既存の FACTIONS / CHAR_FACTION の数値はそのまま、 描画レイヤだけ拡大
const REL_FACTION_SCALE = 1.5;
const REL_CHAR_SCALE = 1.25;
function _scaledFactionPos(f) {
  return { x: f.x * REL_FACTION_SCALE, y: f.y * REL_FACTION_SCALE };
}
function getCharPos(name) {
  const meta = CHAR_FACTION[name];
  if (!meta) return null;
  const f = FACTIONS.find(x => x.id === meta.f);
  if (!f) return null;
  const fp = _scaledFactionPos(f);
  return { x: fp.x + meta.dx * REL_CHAR_SCALE, y: fp.y + meta.dy * REL_CHAR_SCALE };
}

function _factionDimOpacity(facId) {
  // focus なし → 1.0、 focus あり&一致 → 1.0、 focus あり&不一致 → 0.18
  if (!_relationsFocusFaction) return 1.0;
  return _relationsFocusFaction === facId ? 1.0 : 0.18;
}

// 未公開章のキャラ/派閥は相関図に出さない (野沢さん指示 2026-05-03 「公開日時に合わせて表示」)
// RELATIONS の登録自体は維持、 描画レイヤだけ抑制
function _isCharReleased(c) {
  return !!c && (!c.chapter || _isChapterReleased(c.chapter));
}
function _factionHasReleasedMember(facId) {
  for (const [name, meta] of Object.entries(CHAR_FACTION)) {
    if (meta.f !== facId) continue;
    const c = getCharByName(name);
    if (c && _isCharReleased(c)) return true;
  }
  return false;
}

// 派閥背景円の半径を派閥のキャラ占有領域から自動算出 (キャラ数差を吸収)
function _factionRadius(facId) {
  let maxDist = 0;
  for (const [name, meta] of Object.entries(CHAR_FACTION)) {
    if (meta.f !== facId) continue;
    const c = getCharByName(name);
    if (!c || !_isCharReleased(c)) continue;
    const d = Math.hypot(meta.dx, meta.dy + 40);  // 円中心は f.y+40 オフセット
    if (d > maxDist) maxDist = d;
  }
  // 最大相対距離 + ノード半径 + 余白、 ×CHAR_SCALE、 最低 175*scale
  return Math.max(175, maxDist + 55) * REL_CHAR_SCALE;
}
function renderFactionBg() {
  return FACTIONS.filter(f => _factionHasReleasedMember(f.id)).map(f => {
    const fp = _scaledFactionPos(f);
    const r = _factionRadius(f.id);
    const op = _factionDimOpacity(f.id);
    return `<circle data-faction-id="${f.id}" class="rel-faction-bg" cx="${fp.x}" cy="${fp.y + 40 * REL_CHAR_SCALE}" r="${r}" fill="${f.color}" fill-opacity="${0.06 * op}" stroke="${f.color}" stroke-opacity="${0.25 * op}" stroke-width="1.5" stroke-dasharray="4,4" style="cursor:pointer"/>`;
  }).join('');
}

function renderFactionLabels() {
  return FACTIONS.filter(f => _factionHasReleasedMember(f.id)).map(f => {
    const fp = _scaledFactionPos(f);
    const r = _factionRadius(f.id);
    const op = _factionDimOpacity(f.id);
    // ラベルは派閥背景円の上端より少し上に配置 (円半径連動)
    const labelY = fp.y + 40 * REL_CHAR_SCALE - r - 15;
    const yomiY = labelY - 22;
    const yomiTxt = f.yomi
      ? `<text x="${fp.x}" y="${yomiY}" text-anchor="middle" fill="${f.color}" font-size="11" letter-spacing="2" opacity="${0.7 * op}" style="text-shadow: 0 0 6px rgba(0,0,0,0.8)">${f.yomi}</text>`
      : '';
    return `${yomiTxt}<text data-faction-id="${f.id}" class="rel-faction-label" x="${fp.x}" y="${labelY}" text-anchor="middle" fill="${f.color}" font-size="22" font-weight="700" letter-spacing="2" opacity="${op}" style="cursor:pointer; text-shadow: 0 0 8px rgba(0,0,0,0.8)">${f.label}</text>`;
  }).join('');
}

// 各タイプ用の矢印マーカー定義
function renderArrowMarkers() {
  const directedTypes = Object.entries(REL_STYLE).filter(([_, s]) => s.directed);
  return directedTypes.map(([type, s]) => `
    <marker id="arrow-${type}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <path d="M 0 0 L 10 5 L 0 10 z" fill="${s.color}" fill-opacity="0.85"/>
    </marker>
  `).join('');
}

function renderRelationLines() {
  const lines = [];
  // 同じペア(a,b)を持つ関係をグループ化 → 上下に振り分けて重なり回避
  const pairGroups = {};
  RELATIONS.forEach((r, idx) => {
    const key = [r.a, r.b].sort().join('|');
    if (!pairGroups[key]) pairGroups[key] = [];
    pairGroups[key].push({ ...r, _idx: idx });
  });

  for (const [, rels] of Object.entries(pairGroups)) {
    const hasDirectional = rels.some(r => (REL_STYLE[r.type] || {}).directed);
    rels.forEach((r, i) => {
      const pa = getCharPos(r.a);
      const pb = getCharPos(r.b);
      if (!pa || !pb) return;
      // 未公開章キャラを含む線は描かない (野沢さん指示 2026-05-03)
      const ca = getCharByName(r.a), cb = getCharByName(r.b);
      if (!_isCharReleased(ca) || !_isCharReleased(cb)) return;
      const style = REL_STYLE[r.type] || REL_STYLE.fellow;
      const dash = style.dash !== 'none' ? `stroke-dasharray="${style.dash}"` : '';

      // 線の方向ベクトル + 垂直単位ベクトル
      const dxL = pb.x - pa.x, dyL = pb.y - pa.y;
      const lineLen = Math.hypot(dxL, dyL) || 1;
      const px = -dyL / lineLen, py = dxL / lineLen;

      // 同ペアでも線そのものは中央のまま (Lineが分散してると関係性が分かりにくい)
      const lineShift = 0;
      let x1 = pa.x + px * lineShift, y1 = pa.y + py * lineShift;
      let x2 = pb.x + px * lineShift, y2 = pb.y + py * lineShift;
      if (style.directed) {
        const trim = 36;
        x2 = x2 - (dxL / lineLen) * trim;
        y2 = y2 - (dyL / lineLen) * trim;
      }
      const marker = style.directed ? `marker-end="url(#arrow-${r.type})"` : '';
      // focus 中は両端のキャラが focus 派閥所属でない関係線を dim
      let lineOp = 0.65;
      if (_relationsFocusFaction) {
        const fa = (CHAR_FACTION[r.a] || {}).f;
        const fb = (CHAR_FACTION[r.b] || {}).f;
        const inFocus = (fa === _relationsFocusFaction) || (fb === _relationsFocusFaction);
        lineOp = inFocus ? 0.85 : 0.10;
      }
      lines.push(`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${style.color}" stroke-opacity="${lineOp}" stroke-width="${style.w}" ${dash} ${marker}/>`);

      // ラベル位置の計算
      const baseOffset = lineLen < 200 ? 26 : 14;
      const minMargin = Math.min(0.45, Math.max(0.32, 80 / lineLen));

      if (style.directed && (r.aRole || r.bRole)) {
        // 方向性ラベル: a/bを線の両側に振り分け (横線なら a=上/b=下)
        // 同ペア複数なら i に応じて回転 (内側スタックが大きくなり過ぎないよう±制御)
        const sideSign = (i % 2 === 0) ? 1 : -1;
        const sideStack = Math.floor(i / 2);
        const dirOffset = sideSign * (baseOffset + sideStack * 30);
        const tA = minMargin, tB = 1 - minMargin;
        const aPerp = dirOffset;
        const bPerp = -dirOffset;
        let ax = pa.x + dxL * tA + px * aPerp;
        let ay = pa.y + dyL * tA + py * aPerp;
        let bx = pa.x + dxL * tB + px * bPerp;
        let by = pa.y + dyL * tB + py * bPerp;
        if (r.aRole) lines.push(relLabel(ax, ay, r.aRole, style.color));
        if (r.bRole) lines.push(relLabel(bx, by, r.bRole, style.color));
      } else if (r.label) {
        // 双方向単一ラベル: 中央 + 垂直オフセット
        // 同ペアに方向性関係がある場合、その aPerp/bPerp と被らないよう更に外側へ
        const sideSign = (i % 2 === 0) ? 1 : -1;
        const sideStack = Math.floor(i / 2);
        let perp = sideSign * (baseOffset + sideStack * 30);
        if (hasDirectional) {
          // directionalの ±baseOffset と被らないよう更に外側 (+36)
          perp = sideSign * (baseOffset + 40 + sideStack * 30);
        }
        let mx = (pa.x + pb.x) / 2 + px * perp;
        let my = (pa.y + pb.y) / 2 + py * perp;
        lines.push(relLabel(mx, my, r.label, style.color));
      }
    });
  }
  return lines.join('');
}

// ラベルを背景プレート付きで描画 (アイコン被り対策で視認性確保)
function relLabel(x, y, text, color) {
  const w = text.length * 13 + 14;
  const h = 18;
  return `<g class="rel-label">
    <rect x="${x - w/2}" y="${y - h/2}" width="${w}" height="${h}" rx="4" fill="rgba(8,12,28,0.92)" stroke="${color}" stroke-opacity="0.45" stroke-width="0.8"/>
    <text x="${x}" y="${y + 4}" text-anchor="middle" fill="${color}" font-size="11" font-weight="700">${text}</text>
  </g>`;
}

function renderCharNodes() {
  const nodes = [];
  for (const [name, meta] of Object.entries(CHAR_FACTION)) {
    if (name.endsWith('_acad')) continue; // ダミーキー除外
    const c = getCharByName(name);
    if (!c) continue;
    if (!_isCharReleased(c)) continue;  // 未公開章キャラは表示しない (野沢さん指示 2026-05-03)
    const pos = getCharPos(name);
    if (!pos) continue;
    const unlocked = isUnlocked(c);
    const tierColor = TIER_COLORS[c.tier][0];
    const r = c.tier === 'LR' ? 36 : c.tier === 'UR' ? 32 : c.tier === 'SSR' ? 28 : 24;
    let opacity = unlocked ? 1 : 0.3;
    // focus 中: focus 派閥のキャラだけ通常 opacity、 他は dim
    if (_relationsFocusFaction && meta.f !== _relationsFocusFaction) {
      opacity = opacity * 0.18;
    }
    const cursor = unlocked ? 'pointer' : 'default';
    // 画像を clipPath で円形クリップ
    const clipId = `clip-${name.replace(/[\s ]/g, '_')}`;
    nodes.push(`
      <g data-char-name="${name}" style="cursor:${cursor}; opacity:${opacity}">
        <defs>
          <clipPath id="${clipId}"><circle cx="${pos.x}" cy="${pos.y}" r="${r}"/></clipPath>
        </defs>
        <circle cx="${pos.x}" cy="${pos.y}" r="${r + 3}" fill="${tierColor}" stroke="${tierColor}" stroke-width="2"/>
        ${unlocked ? `<image href="${c.img}" x="${pos.x - r}" y="${pos.y - r}" width="${r*2}" height="${r*2}" clip-path="url(#${clipId})" preserveAspectRatio="xMidYMid slice"/>`
                    : `<circle cx="${pos.x}" cy="${pos.y}" r="${r}" fill="#222"/><text x="${pos.x}" y="${pos.y + 6}" text-anchor="middle" fill="#888" font-size="16">?</text>`}
        <text x="${pos.x}" y="${pos.y + r + 16}" text-anchor="middle" fill="#fff" font-size="12" font-weight="700" style="text-shadow: 0 0 6px rgba(0,0,0,1), 0 0 4px rgba(0,0,0,1)">${unlocked ? name : '???'}</text>
      </g>`);
  }
  return nodes.join('');
}

// ───── 画像拡大 (ズーム/パン対応) ─────
let zoomScale = 1, zoomTx = 0, zoomTy = 0;
let zoomMouseDown = false;
let zoomDragging = false, zoomStartX = 0, zoomStartY = 0, zoomBaseTx = 0, zoomBaseTy = 0;
const ZOOM_LEVELS = [1, 1.5, 2.5, 4];

function applyZoomTransform() {
  const img = $("#char-img-zoom-img");
  img.style.transform = `translate(${zoomTx}px, ${zoomTy}px) scale(${zoomScale})`;
  img.style.cursor = zoomScale > 1 ? "grab" : "zoom-in";
  $("#char-img-zoom-level").textContent = zoomScale.toFixed(1) + "x";
}

function resetZoom() {
  zoomScale = 1; zoomTx = 0; zoomTy = 0;
  applyZoomTransform();
}

function toggleCharImgZoom() {
  const z = $("#char-img-zoom");
  if (z.classList.contains("active")) {
    closeImgZoom();
  } else {
    resetZoom();
    z.classList.add("active");
  }
}

// 場所画像 (背景 + 挿絵) を拡大表示 — char-img-zoom モーダルを流用
// 引数 src は原寸 PNG パス (thumb 渡しても _thumb.webp → .png 置換する保険つき)
let _locImgZoomLocked = false;  // openLocImageZoom経由かのフラグ (char-detail経由の toggleCharImgZoom との lock pair 干渉を回避)
function openLocImageZoom(src) {
  const z = document.getElementById('char-img-zoom');
  const img = document.getElementById('char-img-zoom-img');
  if (!z || !img || !src) return;
  const fullSrc = toFullUrl(src);
  img.src = fullSrc;
  // 原寸PNGが404 の場合は thumb webp にフォールバック
  img.onerror = function () {
    this.onerror = null;
    this.src = src;
  };
  resetZoom();
  z.classList.add('active');
  _lockBodyScroll();  // モーダル背景 scroll lock (必須、 過去ルール feedback_modal_background_lock.md)
  _locImgZoomLocked = true;
}

function closeImgZoom() {
  $("#char-img-zoom").classList.remove("active");
  resetZoom();
  // openLocImageZoom 経由の時のみ scroll lock 解除 (char-detail内の toggleCharImgZoom 経由は元々 lockしてないのでペア崩れ防止)
  if (_locImgZoomLocked) {
    _unlockBodyScroll();
    _locImgZoomLocked = false;
  }
}

// dir: 1=拡大段階, -1=縮小段階, 0=リセット
function zoomImg(dir) {
  if (dir === 0) { resetZoom(); return; }
  const cur = ZOOM_LEVELS.findIndex(l => Math.abs(l - zoomScale) < 0.05);
  let nextIdx;
  if (cur >= 0) {
    nextIdx = Math.max(0, Math.min(ZOOM_LEVELS.length - 1, cur + dir));
  } else {
    // 連続ズームの中間値からは最も近い段に飛ばす
    nextIdx = ZOOM_LEVELS.findIndex(l => l > zoomScale);
    if (nextIdx === -1) nextIdx = ZOOM_LEVELS.length - 1;
    if (dir < 0) nextIdx = Math.max(0, nextIdx - 1);
  }
  zoomScale = ZOOM_LEVELS[nextIdx];
  // リセット位置に戻す (中央揃え)
  if (zoomScale === 1) { zoomTx = 0; zoomTy = 0; }
  applyZoomTransform();
}

// 画像クリックで段階ズーム (デスクトップ/モバイル共通)
function onZoomImgClick(e) {
  e.stopPropagation();
  if (zoomDragging) return;
  // 1x→1.5x→2.5x→4x→1x ループ
  const cur = ZOOM_LEVELS.findIndex(l => Math.abs(l - zoomScale) < 0.05);
  const nextIdx = (cur + 1) % ZOOM_LEVELS.length;
  zoomScale = ZOOM_LEVELS[nextIdx];
  if (zoomScale === 1) { zoomTx = 0; zoomTy = 0; }
  applyZoomTransform();
}

// ドラッグで移動 (mousedown/touchstart で初めて有効化)
function onZoomDragStart(e) {
  if (zoomScale <= 1) return;
  // 左クリックのみ反応 (右クリック等を弾く)
  if (e.type === 'mousedown' && e.button !== 0) return;
  // ブラウザの画像ドラッグ(D&D)を抑止
  e.preventDefault();
  zoomMouseDown = true;
  zoomDragging = false;
  const isTouch = e.type === 'touchstart';
  const x = isTouch ? e.touches[0].clientX : e.clientX;
  const y = isTouch ? e.touches[0].clientY : e.clientY;
  zoomStartX = x; zoomStartY = y;
  zoomBaseTx = zoomTx; zoomBaseTy = zoomTy;
  const img = $("#char-img-zoom-img");
  img.style.cursor = "grabbing";
  img.style.transition = "none";  // ドラッグ中はtransition無効化(遅延防止)
}
function onZoomDragMove(e) {
  if (!zoomMouseDown) return;       // ★ 押されてない時は無視
  if (zoomScale <= 1) return;
  const isTouch = e.type === 'touchmove';
  const x = isTouch ? e.touches[0].clientX : e.clientX;
  const y = isTouch ? e.touches[0].clientY : e.clientY;
  const dx = x - zoomStartX, dy = y - zoomStartY;
  if (Math.abs(dx) > 4 || Math.abs(dy) > 4) zoomDragging = true;
  if (zoomDragging) {
    zoomTx = zoomBaseTx + dx;
    zoomTy = zoomBaseTy + dy;
    applyZoomTransform();
    if (isTouch) e.preventDefault();
  }
}
function onZoomDragEnd() {
  zoomMouseDown = false;
  const img = $("#char-img-zoom-img");
  img.style.cursor = zoomScale > 1 ? "grab" : "zoom-in";
  img.style.transition = "";  // ドラッグ終了でtransition復活 (ボタン等のスムーズ動作)
  setTimeout(() => { zoomDragging = false; }, 30);
}

// 滑車ズーム
function onZoomWheel(e) {
  e.preventDefault();
  const dir = e.deltaY < 0 ? 0.15 : -0.15;
  const newScale = Math.max(1, Math.min(6, zoomScale + dir));
  zoomScale = newScale;
  if (zoomScale === 1) { zoomTx = 0; zoomTy = 0; }
  applyZoomTransform();
}

function closeCharDetail() {
  $("#char-detail").classList.remove("active");
  $("#char-img-zoom").classList.remove("active");
  _unlockBodyScroll();
  // 詳細閉じた時にホーム/図鑑カードのNEWバッジを再描画 (galleryViewed 反映)
  try { if (typeof renderHomeGallery === 'function') renderHomeGallery(); } catch (e) {}
  try { if ($("#gallery").classList.contains("active") && typeof renderGalleryByTab === 'function') renderGalleryByTab(); } catch (e) {}
}

// ────────────── Bindings ──────────────
// 通常ガチャ
$("#btn-single").addEventListener("click", () => doSingle());
$("#btn-ten").addEventListener("click", () => doTen());
// ピックアップガチャ
$("#btn-single-pickup")?.addEventListener("click", () => doSingle({ pickup: PICKUP_CHAPTER }));
$("#btn-ten-pickup")?.addEventListener("click", () => doTen({ pickup: PICKUP_CHAPTER }));
$("#btn-rate-detail")?.addEventListener("click", () => showRateDetail());

// ピックアップ章ラベルを PICKUP_CHAPTER から自動更新 (HTMLハードコード回避、 章バンプ時の更新漏れ防止)
function updatePickupChapterLabels() {
  const m = String(PICKUP_CHAPTER || '').match(/s\d+c(\d+)/);
  const chapterNum = m ? m[1] : '?';
  const label = `第${chapterNum}章`;
  const labelEl = document.getElementById('pickup-chapter-label');
  const subEl = document.getElementById('pickup-chapter-sub');
  const noteEl = document.getElementById('pickup-note');
  if (labelEl) labelEl.textContent = label;
  if (subEl) subEl.textContent = `${label}キャラ ×2倍`;
  if (noteEl) noteEl.textContent = `+ ${label} ×2`;
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', updatePickupChapterLabels);
} else {
  updatePickupChapterLabels();
}
$("#result-close").addEventListener("click", closeResult);
$("#result-close-top")?.addEventListener("click", closeResult);
const _resultAgainTen = () => {
  closeResult();
  setTimeout(() => doTen(), 100);
};
$("#result-again-ten").addEventListener("click", _resultAgainTen);
$("#result-again-ten-top")?.addEventListener("click", _resultAgainTen);
$("#result").addEventListener("click", e => { if (e.target.id === "result") closeResult(); });
$("#btn-gallery").addEventListener("click", openGallery);
$("#btn-relations").addEventListener("click", openRelations);
$("#btn-worldmap")?.addEventListener("click", openWorldMap);

// ============ ワールドマップ (Phase 2) ============
// Phase 1 (v1.2.3): 14派閥を世界地図風に配置 + 派閥タップで side panel
// Phase 2 (v1.4.x): 章マーカー (主舞台にホットスポット、 タップで章へジャンプ) + S2 派閥ティザー (霧表現) + pinch-zoom/pan
let _worldMapActiveFaction = null;
let _worldMapZoomState = null; // { scale, tx, ty } セッション中保持

// 章マーカー: 各章の主舞台座標。 公開済み章は openStory、 公開予定章 (releaseDate あり) は Coming Soon バッジ
// 2026-05-01 調整: 画像端からの見切れ + 派閥アイコン + S2/S3ティザーとの重なり 回避
const STORY_CHAPTER_MARKERS = [
  { storyId: 's1c1', label: '第1章', icon: '✨', x: 1330, y: 1100 }, // 星霊学院 academy 北西、 上に少し上げて派閥円との距離確保
  { storyId: 's1c2', label: '第2章', icon: '🌊', x:  900, y: 1380 }, // アクアシス aquasis 南西、 内側に少し移動
  { storyId: 's1c3', label: '第3章', icon: '🐉', x: 1670, y: 1380 }, // 砂漠サハール (派閥未登録、 専用座標)、 ???ティザーから離す
  { storyId: 's1c4', label: '第4章', icon: '❄️', x: 1700, y:  220 }, // 凍土+空 (北方東部、 Coming Soon)、 内側に下げてコンパスローズと干渉回避
  { storyId: 's1c5', label: '第5章', icon: '🌑', x:  300, y: 1380 }, // 銀霜+黒月衆+地底市 (西方氷土の裏側)、 silver(500,1250) の少し南西
];
// S2/S3 派閥ティザー (霧表現): まだ実装されていない領域を「???」 で示す
// 画像範囲外は viewBox bg で見えにくいため内側に配置
const STORY_FACTION_TEASER = [
  { id: 'season2', label: '???', subLabel: '— Season 2 領域 —', x:  150, y: 1500 },
  { id: 'season3', label: '???', subLabel: '— 始原の地 —',     x: 1850, y: 1500 },
];

// ワールドマップ open/close 状態管理 (hidden attribute ではなく内部フラグで lock pair を厳密管理)
// 2026-05-02 修正: hidden attribute だけで判定すると、 char-detail/img-zoom 等の経由で
// hidden state が想定外に変化した時に lock pair が崩れて button 反応しなくなる問題対策
let _worldMapIsOpen = false;
async function openWorldMap() {
  const m = document.getElementById('world-map');
  if (!m) return;
  // 状態不整合の自己修復: 内部 open フラグ true なのに UI 上は hidden の場合、 lock pair が壊れてる
  // ボタン反応しない事故対策 (野沢さん指摘 2026-05-02「WM中に何かクリック後 Esc で反応しなくなる」)
  if (_worldMapIsOpen && m.hasAttribute('hidden')) {
    _worldMapIsOpen = false;
    _unlockBodyScroll();
  }
  // ワールドマップ画像 (約 3.5MB) を事前 fetch — 未cacheなら 「読込中」 オーバーレイ
  const wmUrl = _appendImgCacheBuster('/images/locations/world_map.png');
  let wmCached = false;
  try { wmCached = !!(await caches.match(wmUrl)); } catch (e) {}
  if (!wmCached) {
    const ov = document.getElementById('world-map-loading-overlay');
    if (ov) ov.hidden = false;
    try { await fetch(wmUrl, { credentials: 'omit' }); } catch (e) { /* オフライン等は無視、 SVG 内 image が再試行する */ }
    if (ov) ov.hidden = true;
  }
  renderWorldMap();
  m.removeAttribute('hidden');
  if (!_worldMapIsOpen) {
    _lockBodyScroll();
    _worldMapIsOpen = true;
  }
}
function closeWorldMap() {
  const m = document.getElementById('world-map');
  if (!m) return;
  m.setAttribute('hidden', '');
  // 内部状態を完全リセット (派閥 active state / side panel) — 次回 open 時に汚れた状態が残らないように
  _worldMapActiveFaction = null;
  const side = document.getElementById('world-map-side');
  if (side) side.innerHTML = '<div class="world-map-side-empty">📍 派閥をタップして詳細表示</div>';
  if (_worldMapIsOpen) {
    _unlockBodyScroll();
    _worldMapIsOpen = false;
  }
  // 全モーダル閉じてれば scroll lock を強制解除 (state mismatch fallback) — modalDepth 漏れによる「WMボタン反応しない」 事故対策
  if (typeof _modalDepth !== 'undefined' && _isAllModalsHidden && _isAllModalsHidden()) {
    if (_modalDepth !== 0) _modalDepth = 0;
    document.body.classList.remove('modal-open');
    document.documentElement.classList.remove('modal-open');
    document.body.style.top = '';
    if (typeof _savedScrollY !== 'undefined') {
      try { window.scrollTo(0, _savedScrollY); } catch (e) {}
    }
  }
}
// 派閥ID → 領地アイコン絵文字 (ファンタジー世界観の象徴を一発で伝える)
const FACTION_ICONS = {
  genso: '✨', rulers: '👑', church: '⛪', dragon: '🐉', redwing: '🔥',
  yakai: '🌑', wolf: '🐺', forest: '🌲', silver: '❄️', tower: '🗼',
  seventh: '☀️', academy: '📚', aquasis: '🌊', crimson: '⚓',
};
// 派閥間の繋がり (関係深い派閥ペア = 道路で結ぶ)
const FACTION_ROUTES = [
  ['genso', 'rulers'], ['rulers', 'church'], ['rulers', 'dragon'],
  ['church', 'forest'], ['dragon', 'redwing'],
  ['forest', 'wolf'], ['redwing', 'yakai'],
  ['wolf', 'silver'], ['yakai', 'seventh'],
  ['silver', 'academy'], ['seventh', 'academy'],
  ['tower', 'rulers'], ['tower', 'academy'],
  ['academy', 'aquasis'], ['aquasis', 'crimson'],
];

// ワールドマップ専用 座標 (相関図 FACTIONS とは独立、 ファンタジー世界の地理を表現)
// viewBox 2000x1600。 上=空界、 中央=大陸、 下=海域
const FACTION_WORLD_COORDS = {
  // 天空界 (浮遊する星の世界)
  genso:   { x: 1000, y:  140, region: '天空界' },
  // 中央 (覇者の都)
  rulers:  { x: 1000, y:  450, region: '中央大陸' },
  tower:   { x: 1000, y:  720, region: '中央大陸' },
  // 西部山岳 (北→南)
  church:  { x:  450, y:  380, region: '西方聖域' },
  forest:  { x:  280, y:  720, region: '西方樹海' },
  wolf:    { x:  330, y: 1010, region: '西方荒野' },
  silver:  { x:  500, y: 1250, region: '西方氷土' },
  // 東部山岳 (北→南)
  dragon:  { x: 1240, y:  550, region: '中央東部紫塔' },  // 2026-05-03 修正 (野沢さん指摘): 黒曜塔 (1000,720) と 空挺城 (1480,380) の間、 紫塔の絵柄に一致
  redwing: { x: 1720, y:  720, region: '東方紅地' },
  yakai:   { x: 1670, y: 1010, region: '東方夜域' },
  seventh: { x: 1500, y: 1250, region: '東方光土' },
  // 南方 (海域近く)
  academy: { x: 1000, y: 1180, region: '中央南部' },
  // 海域 (一番南)
  aquasis: { x:  800, y: 1450, region: '南方海域' },
  crimson: { x: 1300, y: 1450, region: '南方海域' },
  // S1C3 追加 (古龍砂漠サハール、 右端の赤茶砂漠)
  sahar:   { x: 1900, y: 1000, region: '東方砂漠' },
  // S1C4 追加 (凍土+空挺、 2026-05-03 登録漏れ修正)
  // niiruru: world_map 右上の氷城群 = 画像絵柄通り
  // zenonia: niiruru の南西近距離 (s1c4 本文「ニーヴル → 南西へ少し迂回 → ゼノニア」 整合 + 旧 dragon 位置の浮遊城絵柄)
  niiruru: { x: 1700, y:  200, region: '北方氷土' },
  zenonia: { x: 1480, y:  380, region: '北方雲海' },
  // S1C5 追加 (黒月衆+地底市リオラ)
  darkmoon: { x:  350, y: 1380, region: '西方氷土の裏側' },  // silver(500,1250) の南西、 月喰いの森・黒月の祭壇地
  liora:    { x:  200, y: 1100, region: '西方山岳地下' },    // silver の北西、 山岳の岩壁裂け目から下る地下都市
  // S1C6 追加 (公開予定)
  shrines:   { x: 1100, y:  950, region: '中央南東' },        // academy(1000,1180) の上、 観測者七座祭祀の中心
  // S1C7 追加 (公開予定、 ヴォイドラ覚醒の異界塔)
  voidtower: { x: 1000, y: 1580, region: '異界 (深淵)' },     // 観測者七座 (天空界) と対の存在、 viewBox 最下層
};

function renderWorldMap() {
  const canvas = document.getElementById('world-map-canvas');
  if (!canvas || typeof FACTIONS === 'undefined') return;
  // 派閥ごとのメンバー数を集計
  const memberCount = {};
  for (const name in (typeof CHAR_FACTION !== 'undefined' ? CHAR_FACTION : {})) {
    const f = CHAR_FACTION[name].f;
    memberCount[f] = (memberCount[f] || 0) + 1;
  }
  const W = 2000, H = 1600;
  // ワールド専用座標を FACTIONS にマージ (相関図用 x,y はそのまま、 ワールド用は FACTION_WORLD_COORDS から)
  const factionMap = Object.fromEntries(FACTIONS.map(f => {
    const wc = FACTION_WORLD_COORDS[f.id];
    return [f.id, wc ? { ...f, x: wc.x, y: wc.y, region: wc.region } : f];
  }));
  const factionsForMap = FACTIONS.map(f => factionMap[f.id]);
  let svg = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet">`;
  // Phase 2 zoom/pan layer: 全描画要素を内包、 transform で zoom/pan 制御
  svg += `<g class="world-zoom-layer">`;
  // 装飾の defs: 大陸グラデ + 海洋 + 派閥ハロー
  svg += `<defs>
    <radialGradient id="land-grad" cx="50%" cy="48%" r="58%">
      <stop offset="0%" stop-color="#3a2858" stop-opacity="0.55"/>
      <stop offset="55%" stop-color="#1a2055" stop-opacity="0.35"/>
      <stop offset="100%" stop-color="#080d22" stop-opacity="0"/>
    </radialGradient>
    <radialGradient id="ocean-grad" cx="50%" cy="50%" r="80%">
      <stop offset="0%" stop-color="#0d1538" stop-opacity="0"/>
      <stop offset="100%" stop-color="#020410" stop-opacity="0.6"/>
    </radialGradient>
    <pattern id="grid-faint" width="80" height="80" patternUnits="userSpaceOnUse">
      <path d="M 80 0 L 0 0 0 80" fill="none" stroke="rgba(200,180,255,0.04)" stroke-width="1"/>
    </pattern>
    <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
      <feGaussianBlur stdDeviation="6" result="b"/>
      <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
    </filter>
  </defs>`;
  // Phase 2 Step B (2026-05-01〜): 手描き風 ワールドマップ背景画像 (1792×1024) を最背面に配置
  // 既存 SVG装飾 (大陸shape / 山脈 / 森 / 海岸線) は画像内に内包、 SVG側からは削除
  // 派閥アイコン + 章マーカー + コンパスローズ + タイトル + S2/S3ティザー は画像の上に重ねる
  // viewBox 2000x1600 (5:4) に対し画像 1792x1024 (16:9) のため、 派閥アイコン (画像範囲外に出る上下) を画像内に収めるため "slice" を採用
  // (「meet」 だと上下に黒余白ができて派閥アイコン+ティザーが画像外に出てしまう、 ユーザー指示で slice に戻す 2026-05-01)
  // 副作用: 画像の左右約400pxが trim される (中央維持)、 ただし派閥配置の整合性を優先
  svg += `<image href="${_appendImgCacheBuster('/images/locations/world_map.png')}" x="0" y="0" width="${W}" height="${H}" preserveAspectRatio="xMidYMid slice" opacity="0.95"/>`;
  // 派閥アイコン視認性向上: 画像の上に薄い暗オーバーレイ (ocean tint のみ、 グリッドは画像と被るので除去)
  svg += `<rect width="${W}" height="${H}" fill="url(#ocean-grad)" opacity="0.2"/>`;
  // コンパスローズ (右下隅)
  svg += `<g transform="translate(1820, 230)">
    <circle r="60" fill="rgba(20,15,45,0.7)" stroke="rgba(255,217,122,0.4)" stroke-width="2"/>
    <polygon points="0,-50 8,0 0,50 -8,0" fill="rgba(255,217,122,0.7)"/>
    <polygon points="-50,0 0,8 50,0 0,-8" fill="rgba(255,217,122,0.4)"/>
    <text y="-32" font-size="18" text-anchor="middle" fill="rgba(255,217,122,0.9)" font-weight="700" stroke="rgba(0,0,0,0.7)" stroke-width="2" paint-order="stroke">N</text>
    <text y="46" font-size="18" text-anchor="middle" fill="rgba(255,217,122,0.9)" font-weight="700" stroke="rgba(0,0,0,0.7)" stroke-width="2" paint-order="stroke">S</text>
    <text x="-52" y="6" font-size="18" text-anchor="middle" fill="rgba(255,217,122,0.7)" font-weight="700" stroke="rgba(0,0,0,0.7)" stroke-width="2" paint-order="stroke">W</text>
    <text x="52" y="6" font-size="18" text-anchor="middle" fill="rgba(255,217,122,0.7)" font-weight="700" stroke="rgba(0,0,0,0.7)" stroke-width="2" paint-order="stroke">E</text>
  </g>`;
  // タイトル装飾 (左上隅、 半透明背景パネル付きで画像と被っても読める)
  svg += `<g transform="translate(40, 40)">
    <rect x="-10" y="-30" width="430" height="80" rx="10" fill="rgba(10,14,29,0.7)" stroke="rgba(255,217,122,0.4)" stroke-width="1.5"/>
    <text x="10" y="10" font-size="36" font-weight="700" fill="rgba(255,217,122,0.95)" stroke="rgba(0,0,0,0.85)" stroke-width="2" paint-order="stroke">🗺️ 虹霊界 大陸地図</text>
    <text x="14" y="38" font-size="14" fill="rgba(200,180,255,0.85)" stroke="rgba(0,0,0,0.7)" stroke-width="1" paint-order="stroke">— Realm of Prismaera —</text>
  </g>`;
  // 派閥間のルート (光の道) — ワールド配置
  FACTION_ROUTES.forEach(([a, b]) => {
    const fa = factionMap[a], fb = factionMap[b];
    if (!fa || !fb) return;
    svg += `<line x1="${fa.x}" y1="${fa.y}" x2="${fb.x}" y2="${fb.y}" stroke="rgba(200,180,255,0.22)" stroke-width="3" stroke-dasharray="8 12" stroke-linecap="round"/>`;
  });
  // 各派閥ノード (ワールド配置)
  factionsForMap.forEach(f => {
    const cnt = memberCount[f.id] || 0;
    const r = 92 + Math.min(cnt * 5, 35);  // 92〜127
    const icon = FACTION_ICONS[f.id] || '⚐';
    svg += `<g class="world-faction-node" data-faction="${f.id}" transform="translate(${f.x},${f.y})">
      <!-- 外周ハロー -->
      <circle r="${r+18}" fill="${f.color}" fill-opacity="0.06" filter="url(#glow)"/>
      <!-- 本体 -->
      <circle r="${r}" fill="${f.color}" fill-opacity="0.25" stroke="${f.color}" stroke-width="4" stroke-opacity="0.9"/>
      <!-- 内側装飾円 -->
      <circle r="${r-14}" fill="none" stroke="${f.color}" stroke-width="1" stroke-opacity="0.5" stroke-dasharray="4 6"/>
      <!-- アイコン -->
      <text y="-10" font-size="58" text-anchor="middle">${icon}</text>
      <!-- ふりがな (上) -->
      <text class="faction-yomi" y="-${r+24}">${escapeHtml(f.yomi)}</text>
      <!-- 派閥名 (中央下) -->
      <text y="40">${escapeHtml(f.label)}</text>
      <!-- メンバー数 (下) -->
      <text class="faction-count" y="${r+42}">${cnt}人</text>
    </g>`;
  });
  // Phase 2: 章マーカー (主舞台に📖ホットスポット、 公開済はopenStory、 未公開はComing Soon)
  STORY_CHAPTER_MARKERS.forEach(m => {
    const isPublished = (typeof STORY_FILES !== 'undefined') && !!STORY_FILES[m.storyId];
    const cls = isPublished ? 'world-chapter-marker' : 'world-chapter-marker coming-soon';
    const cap = isPublished ? m.label : `${m.label} 近日`;
    svg += `<g class="${cls}" data-story="${m.storyId}" transform="translate(${m.x},${m.y})">
      <circle r="46" class="chapter-pulse" />
      <circle r="38" />
      <text class="chapter-icon" y="-4">${m.icon}</text>
      <text class="chapter-label" y="22">${escapeHtml(cap)}</text>
    </g>`;
  });
  // Phase 2: S2/S3 派閥ティザー (霧表現、 タップで Coming Soon toast)
  STORY_FACTION_TEASER.forEach(t => {
    svg += `<g class="world-faction-teaser" data-teaser="${t.id}" transform="translate(${t.x},${t.y})">
      <circle r="80" class="teaser-fog" />
      <circle r="60" class="teaser-core" />
      <text class="teaser-q" y="20">${escapeHtml(t.label)}</text>
      <text class="teaser-sub" y="100">${escapeHtml(t.subLabel)}</text>
    </g>`;
  });
  svg += `</g>`; // close .world-zoom-layer
  // ズームコントロール (zoom-layer の外、 viewBox 右上に固定)
  svg += `<g class="world-zoom-controls" transform="translate(${W-180},80)">
    <rect x="0" y="0" width="160" height="48" rx="24" fill="rgba(10,14,29,0.85)" stroke="rgba(200,180,255,0.3)" stroke-width="1.5"/>
    <g class="zoom-btn" data-zoom="out" transform="translate(28,24)">
      <circle r="18" fill="rgba(255,255,255,0.08)"/>
      <text y="9" font-size="28" fill="#e8ecff" text-anchor="middle" pointer-events="none">−</text>
    </g>
    <g class="zoom-btn" data-zoom="reset" transform="translate(80,24)">
      <circle r="18" fill="rgba(255,255,255,0.08)"/>
      <text y="9" font-size="20" fill="#e8ecff" text-anchor="middle" pointer-events="none">⊙</text>
    </g>
    <g class="zoom-btn" data-zoom="in" transform="translate(132,24)">
      <circle r="18" fill="rgba(255,255,255,0.08)"/>
      <text y="9" font-size="28" fill="#e8ecff" text-anchor="middle" pointer-events="none">+</text>
    </g>
  </g>`;
  svg += `</svg>`;
  canvas.innerHTML = svg;
  // Phase 2: 章マーカー click → 章ギャラリー (場所画像 + キャラ) を side panel に表示。 drag距離 4px 超は click 無視
  canvas.querySelectorAll('.world-chapter-marker').forEach(node => {
    node.addEventListener('click', (e) => {
      if ((svgEl && (svgEl.__worldMapDragDist || 0) > 4)) return;
      e.stopPropagation();
      const sid = node.dataset.story;
      if (node.classList.contains('coming-soon')) {
        _showWorldMapToast(`📅 ${sid.toUpperCase()} は近日公開予定`);
        return;
      }
      _showChapterGallery(sid);
      canvas.querySelectorAll('.world-chapter-marker.active, .world-faction-node.active').forEach(n => n.classList.remove('active'));
      node.classList.add('active');
    });
  });
  // Phase 2: S2/S3 ティザー click → Coming Soon toast、 drag距離 4px 超は click 無視
  canvas.querySelectorAll('.world-faction-teaser').forEach(node => {
    node.addEventListener('click', (e) => {
      if ((svgEl && (svgEl.__worldMapDragDist || 0) > 4)) return;
      e.stopPropagation();
      _showWorldMapToast('🌫️ 未公開領域 — 物語の進行で姿を現します');
    });
  });
  // Phase 2: zoom/pan handler 設定 + zoom controls binding
  const svgEl = canvas.querySelector('svg');
  const zoomLayer = canvas.querySelector('.world-zoom-layer');
  if (svgEl && zoomLayer) _setupWorldMapZoomPan(svgEl, zoomLayer);
  // クリックバインド (drag距離 4px 超は click 無視 — pan 操作と区別)
  canvas.querySelectorAll('.world-faction-node').forEach(node => {
    node.addEventListener('click', () => {
      if ((svgEl && (svgEl.__worldMapDragDist || 0) > 4)) return;
      const fid = node.dataset.faction;
      _showFactionSide(fid);
      canvas.querySelectorAll('.world-faction-node.active').forEach(n => n.classList.remove('active'));
      node.classList.add('active');
    });
  });
  // 前回開いていた派閥があれば自動選択
  if (_worldMapActiveFaction) {
    const prev = canvas.querySelector(`.world-faction-node[data-faction="${_worldMapActiveFaction}"]`);
    if (prev) prev.click();
  } else {
    document.getElementById('world-map-side').innerHTML = '<div class="world-map-side-empty">📍 派閥をタップして詳細表示</div>';
  }
}
function _showFactionSide(fid) {
  _worldMapActiveFaction = fid;
  const side = document.getElementById('world-map-side');
  if (!side) return;
  const fac = FACTIONS.find(f => f.id === fid);
  if (!fac) return;
  // 該当派閥の全キャラ
  const chars = [];
  for (const name in CHAR_FACTION) {
    if (CHAR_FACTION[name].f !== fid) continue;
    const c = getCharByName ? getCharByName(name) : null;
    chars.push({ name, char: c });
  }
  // BGM 有無
  const factionBgmIds = ['church', 'aquasis', 'crimson'];
  const hasBgm = factionBgmIds.includes(fid);
  let html = `<h3>${escapeHtml(fac.label)}</h3>`;
  html += `<div class="faction-yomi-side">${escapeHtml(fac.yomi)}</div>`;
  html += `<div class="world-map-side-meta">`;
  html += `<span>👥 ${chars.length}人</span>`;
  html += hasBgm ? `<span style="color:#fcd34d">🎵 派閥BGM有</span>` : `<span style="color:rgba(255,255,255,0.4)">🎵 BGM無</span>`;
  html += `</div>`;
  html += `<div class="world-map-side-members">`;
  chars.forEach(({ name, char }) => {
    const unlocked = char && (typeof isUnlocked === 'function' ? isUnlocked(char) : false);
    const cls = unlocked ? 'world-map-side-member' : 'world-map-side-member locked';
    const img = char && char.img ? `<img src="${char.img}" alt="${escapeHtml(name)}" loading="lazy">` : '';
    const display = unlocked ? escapeHtml(name) : '🔒';
    html += `<div class="${cls}" data-name="${escapeHtml(name)}">${img}<div>${display}</div></div>`;
  });
  html += `</div>`;
  side.innerHTML = html;
  // メンバークリックでキャラ詳細
  side.querySelectorAll('.world-map-side-member:not(.locked)').forEach(el => {
    el.addEventListener('click', () => {
      const name = el.dataset.name;
      const c = getCharByName ? getCharByName(name) : null;
      if (c && typeof showCharDetail === 'function') showCharDetail(c);
    });
  });
}

// Phase 2: 章ギャラリー — 章マーカータップで該当章の場所画像 + 登場キャラを side panel に表示
// 仕様: ストーリーに飛ばさず、 イラスト/キャラの一覧鑑賞専用 (野沢方針 2026-05-01)
function _showChapterGallery(storyId) {
  _worldMapActiveFaction = null; // 派閥選択をリセット (章ギャラリー優先表示)
  const side = document.getElementById('world-map-side');
  if (!side) return;
  const outline = (typeof STORY_OUTLINE !== 'undefined') ? STORY_OUTLINE.find(c => c.id === storyId) : null;
  if (!outline) return;
  // 場所画像を集約 (背景 + 挿絵) — ロック判定は scenesReached (実際に開いたシーンの記録) で行う
  const bgConf = (typeof LOCATION_CONFIG !== 'undefined') ? (LOCATION_CONFIG[storyId] || {}) : {};
  const inlineConf = (typeof STORY_LOCATION_INLINE_CONFIG !== 'undefined') ? (STORY_LOCATION_INLINE_CONFIG[storyId] || []) : [];
  // 章の進捗: scenesReached = { 'X-Y': 1, ... } 実際に開いたシーンのみ 1
  const progress = (typeof state === 'object' && state && state.storyProgress) ? state.storyProgress[storyId] : null;
  const isCompleted = !!(progress && progress.completed);
  const reached = (progress && progress.scenesReached) || {};
  const lockOf = (sceneLabel) => {
    if (isCompleted) return false;  // 完読すれば全解放
    return !reached[sceneLabel];     // 実際に開いたシーン (=1) のみ表示、 未訪問は ロック
  };
  const locations = [];
  for (const sceneKey in bgConf) {
    if (bgConf[sceneKey] && bgConf[sceneKey].img) {
      locations.push({ scene: sceneKey, kind: '背景', img: bgConf[sceneKey].img, locked: lockOf(sceneKey) });
    }
  }
  inlineConf.forEach(e => {
    if (e && e.img) locations.push({ scene: e.scene, kind: '挿絵', img: e.img, locked: lockOf(e.scene) });
  });
  // シーン順にソート (1-1, 1-2, ..., エピローグ)
  locations.sort((a, b) => _sceneLabelToOrd(a.scene) - _sceneLabelToOrd(b.scene));
  // 該当章のキャラを POOL から抽出 (chapter === storyId)
  const chars = [];
  if (typeof POOL !== 'undefined') {
    for (const tier of ['LR', 'UR', 'SSR', 'SR', 'R']) {
      (POOL[tier] || []).forEach(c => {
        if (c && c.chapter === storyId) chars.push({ ...c, tier });
      });
    }
  }
  // HTML 組み立て
  let html = `<h3>${escapeHtml(outline.icon || '📖')} ${escapeHtml(outline.title)}</h3>`;
  html += `<div class="faction-yomi-side">${escapeHtml(outline.meta)}</div>`;
  // タブフィルター: すべて / 場所 / キャラ
  html += `<div class="chapter-gallery-tabs">`;
  html += `<button type="button" class="chapter-tab active" data-tab="all">すべて</button>`;
  html += `<button type="button" class="chapter-tab" data-tab="loc">🖼️ 場所 ${locations.length}枚</button>`;
  html += `<button type="button" class="chapter-tab" data-tab="char">👥 キャラ ${chars.length}人</button>`;
  html += `</div>`;
  if (outline.tagline) {
    html += `<div class="chapter-gallery-tagline">${escapeHtml(outline.tagline)}</div>`;
  }
  // 場所画像セクション
  if (locations.length > 0) {
    const lockedCount = locations.filter(l => l.locked).length;
    html += `<div class="chapter-gallery-section chapter-gallery-section-loc">`;
    html += `<div class="chapter-gallery-section-title">🖼️ 場所</div>`;
    if (lockedCount > 0 && !isCompleted) {
      html += `<div class="chapter-gallery-lock-note">📖 未到達シーンの画像はロック中 (シーンを読むと解放)</div>`;
    }
    html += `<div class="chapter-gallery-locations">`;
    locations.forEach((loc, idx) => {
      const cls = loc.locked ? 'chapter-gallery-loc locked' : 'chapter-gallery-loc';
      html += `<div class="${cls}" data-img="${escapeHtml(loc.img)}" data-scene="${escapeHtml(loc.scene)}" data-idx="${idx}" data-locked="${loc.locked ? '1' : '0'}">`;
      html += `<img src="${escapeHtml(loc.img)}" alt="${escapeHtml(loc.scene)}" loading="lazy">`;
      if (loc.locked) {
        html += `<div class="chapter-gallery-loc-lockbadge">🔒</div>`;
      }
      const kindCls = loc.kind === '背景' ? 'kind-bg' : (loc.kind === '挿絵' ? 'kind-ill' : 'kind-other');
      html += `<div class="chapter-gallery-loc-label"><span class="chapter-gallery-loc-kind ${kindCls}">${escapeHtml(loc.kind)}</span> ${escapeHtml(loc.scene)}</div>`;
      html += `</div>`;
    });
    html += `</div>`;
    html += `</div>`;
  }
  // キャラセクション
  if (chars.length > 0) {
    html += `<div class="chapter-gallery-section chapter-gallery-section-char">`;
    html += `<div class="chapter-gallery-section-title">👥 登場キャラ</div>`;
    html += `<div class="world-map-side-members">`;
    chars.forEach(c => {
      const unlocked = (typeof isUnlocked === 'function') ? isUnlocked(c) : false;
      const cls = unlocked ? 'world-map-side-member' : 'world-map-side-member locked';
      const img = c.img ? `<img src="${escapeHtml(c.img)}" alt="${escapeHtml(c.name)}" loading="lazy">` : '';
      const display = unlocked ? escapeHtml(c.name) : '🔒';
      html += `<div class="${cls}" data-name="${escapeHtml(c.name)}">${img}<div>${display}</div></div>`;
    });
    html += `</div>`;
    html += `</div>`;
  }
  side.innerHTML = html;
  // タブ click → section フィルター
  const applyTab = (tab) => {
    side.querySelectorAll('.chapter-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
    const showLoc  = (tab === 'all' || tab === 'loc');
    const showChar = (tab === 'all' || tab === 'char');
    side.querySelectorAll('.chapter-gallery-section-loc').forEach(s => { s.style.display = showLoc ? '' : 'none'; });
    side.querySelectorAll('.chapter-gallery-section-char').forEach(s => { s.style.display = showChar ? '' : 'none'; });
  };
  side.querySelectorAll('.chapter-tab').forEach(btn => {
    btn.addEventListener('click', () => applyTab(btn.dataset.tab));
  });
  // 場所画像 click → 拡大 (既存 openLocImageZoom 流用 + nav context で前後ナビ)
  // ロック中の画像は click 無効、 toast で通知
  // ナビゲーション対象は unlocked 画像のみに限定 (ロック画像をスキップ)
  const visibleLocs = locations.filter(l => !l.locked);
  side.querySelectorAll('.chapter-gallery-loc').forEach((el) => {
    el.addEventListener('click', () => {
      if (el.dataset.locked === '1') {
        _showWorldMapToast('🔒 該当シーンを読むと解放されます');
        return;
      }
      // ナビ対象は visibleLocs (unlocked のみ)、 該当の index を visibleLocs 内で再計算
      const sceneKey = el.dataset.scene;
      const visIdx = visibleLocs.findIndex(l => l.scene === sceneKey && l.img === el.dataset.img);
      if (visIdx < 0) return;
      const thumbUrl = el.dataset.img;
      const fullUrl = toFullUrl(thumbUrl);
      _openLocImageZoom(fullUrl, { list: visibleLocs, index: visIdx });
    });
  });
  // キャラ click → キャラ詳細 (既存)
  side.querySelectorAll('.world-map-side-member:not(.locked)').forEach(el => {
    el.addEventListener('click', () => {
      const name = el.dataset.name;
      const c = (typeof getCharByName === 'function') ? getCharByName(name) : null;
      if (c && typeof showCharDetail === 'function') showCharDetail(c);
    });
  });
}

// 場所画像拡大 (openLocImageZoom 流用 + 章ギャラリー用 nav context)
// navContext: { list: [{img, scene, kind}], index } — 渡されたら前後ナビUI を表示
function _openLocImageZoom(url, navContext) {
  if (typeof openLocImageZoom === 'function') {
    openLocImageZoom(url);
  } else {
    const zoom = document.getElementById('char-img-zoom');
    const img = document.getElementById('char-img-zoom-img');
    if (zoom && img) { img.src = url; zoom.classList.add('active'); }
  }
  // navigation: list が 2枚以上なら prev/next + counter UI を inject
  _locZoomNav = (navContext && navContext.list && navContext.list.length >= 2) ? { ...navContext } : null;
  _renderLocZoomNav();
}

let _locZoomNav = null;  // 章ギャラリー側の prev/next nav state

function _renderLocZoomNav() {
  const z = document.getElementById('char-img-zoom');
  if (!z) return;
  // 既存 nav UI を削除 (再描画用)
  const oldNav = z.querySelector('.loc-zoom-nav');
  if (oldNav) oldNav.remove();
  if (!_locZoomNav) return;
  const { list, index } = _locZoomNav;
  if (!list || list.length < 2) return;
  const nav = document.createElement('div');
  nav.className = 'loc-zoom-nav';
  nav.innerHTML = `
    <button type="button" class="loc-zoom-nav-btn prev" aria-label="前の画像">‹</button>
    <div class="loc-zoom-nav-counter">${index + 1} / ${list.length}</div>
    <button type="button" class="loc-zoom-nav-btn next" aria-label="次の画像">›</button>
  `;
  z.appendChild(nav);
  nav.querySelector('.prev').addEventListener('click', (e) => { e.stopPropagation(); _locZoomNavGo(-1); });
  nav.querySelector('.next').addEventListener('click', (e) => { e.stopPropagation(); _locZoomNavGo(1); });
}

function _locZoomNavGo(dir) {
  if (!_locZoomNav) return;
  const { list, index } = _locZoomNav;
  const newIdx = (index + dir + list.length) % list.length;
  _locZoomNav.index = newIdx;
  const next = list[newIdx];
  if (!next || !next.img) return;
  const fullSrc = toFullUrl(next.img);
  const img = document.getElementById('char-img-zoom-img');
  if (img) {
    img.src = fullSrc;
    img.onerror = function () { this.onerror = null; this.src = next.img; };
  }
  // ズーム状態を 1x にリセット (新しい画像で改めてズーム可能に)
  if (typeof zoomImg === 'function') zoomImg(0);
  _renderLocZoomNav();
}

// キーボード ←→ で navigation (章ギャラリー nav active 時のみ)
document.addEventListener('keydown', (e) => {
  const z = document.getElementById('char-img-zoom');
  if (!z || !z.classList.contains('active')) return;
  if (!_locZoomNav) return;
  if (e.key === 'ArrowLeft')  { e.preventDefault(); _locZoomNavGo(-1); }
  else if (e.key === 'ArrowRight') { e.preventDefault(); _locZoomNavGo(1); }
});

// closeImgZoom 時に nav state クリア (UIは DOM 削除で連動)
const _origCloseImgZoom = (typeof closeImgZoom === 'function') ? closeImgZoom : null;
if (_origCloseImgZoom) {
  closeImgZoom = function() {
    _locZoomNav = null;
    const z = document.getElementById('char-img-zoom');
    if (z) { const n = z.querySelector('.loc-zoom-nav'); if (n) n.remove(); }
    return _origCloseImgZoom.apply(this, arguments);
  };
}

// touch swipe で前後ナビ (章ギャラリー nav active時のみ)
(function setupLocZoomSwipe() {
  let sx = 0, sy = 0, swiping = false;
  const z = () => document.getElementById('char-img-zoom');
  document.addEventListener('touchstart', (e) => {
    const zoom = z();
    if (!zoom || !zoom.classList.contains('active')) return;
    if (!_locZoomNav) return;
    if (typeof zoomScale !== 'undefined' && zoomScale > 1.05) return;  // 拡大中は swipe 抑止 (pan優先)
    if (e.touches.length !== 1) return;
    sx = e.touches[0].clientX;
    sy = e.touches[0].clientY;
    swiping = true;
  }, { passive: true });
  document.addEventListener('touchend', (e) => {
    if (!swiping) return;
    swiping = false;
    if (!_locZoomNav) return;
    const t = (e.changedTouches && e.changedTouches[0]) || null;
    if (!t) return;
    const dx = t.clientX - sx;
    const dy = t.clientY - sy;
    if (Math.abs(dx) < 40 || Math.abs(dx) < Math.abs(dy) * 1.2) return; // 横スワイプ判定
    if (dx < 0) _locZoomNavGo(1);
    else _locZoomNavGo(-1);
  }, { passive: true });
})();

// Phase 2: ワールドマップ用 toast (Coming Soon等) — 中央下に1.6秒表示
let _worldMapToastTimer = null;
function _showWorldMapToast(text) {
  const canvas = document.getElementById('world-map-canvas');
  if (!canvas) return;
  let toast = canvas.querySelector('.world-map-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.className = 'world-map-toast';
    canvas.appendChild(toast);
  }
  toast.textContent = text;
  toast.classList.add('show');
  if (_worldMapToastTimer) clearTimeout(_worldMapToastTimer);
  _worldMapToastTimer = setTimeout(() => { toast.classList.remove('show'); }, 1600);
}

// Phase 2: pinch-zoom + pan + zoom controls
// 仕様: scale 1〜2.5、 wheel/pinch で cursor anchored zoom、 drag で pan、 dblclick で reset
//      派閥ノードや章マーカーの click は drag 移動量 4px未満の場合のみ通す
function _setupWorldMapZoomPan(svg, layer) {
  const W = 2000, H = 1600;
  const MIN = 1.0, MAX = 2.5;
  // セッション保持された state があれば復元
  let scale = (_worldMapZoomState && _worldMapZoomState.scale) || 1;
  let tx    = (_worldMapZoomState && _worldMapZoomState.tx)    || 0;
  let ty    = (_worldMapZoomState && _worldMapZoomState.ty)    || 0;
  // pan時の click 抑止 (pointerdown→up間の累積距離)。
  // svg.__worldMapDragDist として公開、 派閥/章マーカー/ティザー click 側が参照
  svg.__worldMapDragDist = 0;
  const update = () => {
    // 範囲ガード: scale=1 の時は強制中央 (tx=ty=0)、 scale>1 は端まで pan 可能 (layer 全幅、 野沢さん指摘 2026-05-03 「右側にスクロールできない」)
    if (scale <= MIN) { scale = MIN; tx = 0; ty = 0; }
    else {
      // 全幅 = (scale-1) * W、 layer の右端が viewport 右端と一致するまで pan 可能
      const maxOff = (scale - 1) * W;
      const maxOffY = (scale - 1) * H;
      tx = Math.max(-maxOff, Math.min(maxOff, tx));
      ty = Math.max(-maxOffY, Math.min(maxOffY, ty));
    }
    layer.setAttribute('transform', `translate(${tx},${ty}) scale(${scale})`);
    _worldMapZoomState = { scale, tx, ty };
  };
  update();
  // wheel zoom (PC)
  svg.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = svg.getBoundingClientRect();
    const px = (e.clientX - rect.left) / rect.width * W;
    const py = (e.clientY - rect.top)  / rect.height * H;
    const factor = e.deltaY > 0 ? 0.9 : 1.1;
    const newScale = Math.max(MIN, Math.min(MAX, scale * factor));
    if (newScale === scale) return;
    // anchor zoom: cursor 位置の SVG 座標を保持
    tx = px - (px - tx) * (newScale / scale);
    ty = py - (py - ty) * (newScale / scale);
    scale = newScale;
    update();
  }, { passive: false });
  // pointer drag + pinch
  // 注意: setPointerCapture は使わない (子要素 click が svg レベルに吸われる挙動を避けるため)
  const pts = new Map();
  let lastDist = null;
  const onPointerDown = (e) => {
    if (e.target.closest('.zoom-btn')) return; // ズームボタン上は pan 開始しない
    pts.set(e.pointerId, { x: e.clientX, y: e.clientY });
    svg.__worldMapDragDist = 0;
  };
  const onPointerMove = (e) => {
    if (!pts.has(e.pointerId)) return;
    const prev = pts.get(e.pointerId);
    const dx = e.clientX - prev.x, dy = e.clientY - prev.y;
    pts.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (pts.size === 1) {
      const rect = svg.getBoundingClientRect();
      const sx = W / rect.width;
      const sy = H / rect.height;
      tx += dx * sx;
      ty += dy * sy;
      svg.__worldMapDragDist = (svg.__worldMapDragDist || 0) + Math.hypot(dx, dy);
      update();
    } else if (pts.size === 2) {
      const arr = [...pts.values()];
      const dist = Math.hypot(arr[0].x - arr[1].x, arr[0].y - arr[1].y);
      if (lastDist) {
        const factor = dist / lastDist;
        const newScale = Math.max(MIN, Math.min(MAX, scale * factor));
        const rect = svg.getBoundingClientRect();
        const cx = (arr[0].x + arr[1].x) / 2;
        const cy = (arr[0].y + arr[1].y) / 2;
        const px = (cx - rect.left) / rect.width * W;
        const py = (cy - rect.top)  / rect.height * H;
        tx = px - (px - tx) * (newScale / scale);
        ty = py - (py - ty) * (newScale / scale);
        scale = newScale;
        update();
        svg.__worldMapDragDist = (svg.__worldMapDragDist || 0) + 10; // pinch中は確実に click 抑止
      }
      lastDist = dist;
    }
  };
  const onPointerUp = (e) => {
    pts.delete(e.pointerId);
    if (pts.size < 2) lastDist = null;
  };
  svg.addEventListener('pointerdown',  onPointerDown);
  svg.addEventListener('pointermove',  onPointerMove);
  svg.addEventListener('pointerup',    onPointerUp);
  svg.addEventListener('pointercancel', onPointerUp);
  svg.addEventListener('pointerleave', onPointerUp);
  // dblclick で reset
  svg.addEventListener('dblclick', (e) => {
    e.preventDefault();
    scale = 1; tx = 0; ty = 0;
    update();
  });
  // ズームコントロール (+ / − / ⊙)
  svg.querySelectorAll('.zoom-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const kind = btn.dataset.zoom;
      if (kind === 'reset') { scale = 1; tx = 0; ty = 0; update(); return; }
      const factor = (kind === 'in') ? 1.3 : (1 / 1.3);
      const newScale = Math.max(MIN, Math.min(MAX, scale * factor));
      if (newScale === scale) return;
      // 中央 anchor zoom
      const cx = W / 2, cy = H / 2;
      tx = cx - (cx - tx) * (newScale / scale);
      ty = cy - (cy - ty) * (newScale / scale);
      scale = newScale;
      update();
    });
  });
}
// B1: モバイル topbar ⋮ メニュー (デスクトップは display:contents で表示なので影響なし)
(function setupTopbarMore() {
  const toggle = document.getElementById('btn-more-toggle');
  const menu = document.getElementById('topbar-secondary');
  const closeBtn = document.getElementById('btn-secondary-close');
  if (!toggle || !menu) return;
  // <dialog> ベースの popup: showModal() で 背景は inert になり完全 block される (OS保証)
  toggle.addEventListener('click', (e) => {
    e.stopPropagation();
    if (menu.open) {
      menu.close();
      toggle.setAttribute('aria-expanded', 'false');
    } else {
      // dialog.showModal が無いブラウザは普通の表示にフォールバック
      if (typeof menu.showModal === 'function') menu.showModal();
      else menu.setAttribute('open', '');
      toggle.setAttribute('aria-expanded', 'true');
    }
  });
  // ✕ ボタンで閉じる
  if (closeBtn) closeBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if (menu.open) menu.close();
    else menu.removeAttribute('open');
    toggle.setAttribute('aria-expanded', 'false');
  });
  // backdrop (::backdrop pseudo) tap で閉じる: dialog の click event は backdrop tap でも element 上で発火
  menu.addEventListener('click', (e) => {
    // dialog 自身がイベントターゲットの時は backdrop タップ
    if (e.target === menu) {
      if (menu.open) menu.close();
      else menu.removeAttribute('open');
      toggle.setAttribute('aria-expanded', 'false');
      return;
    }
    // 内部ボタン押下時も閉じる (操作後はメニュー隠したい)
    if (e.target.closest('button, a')) {
      if (menu.open) menu.close();
      else menu.removeAttribute('open');
      toggle.setAttribute('aria-expanded', 'false');
    }
  });
})();

// ───── ストーリービューワー (紙芝居風) ─────
const STORY_FILES = {
  s1c1: { title: '序: 七座の使命', meta: 'Season 1 — 第1章', file: 'STORY/s1c1.md' },
  s1c2: { title: '南方海域の異変', meta: 'Season 1 — 第2章', file: 'STORY/s1c2.md' },
  s1c3: { title: '砂塵の隊商', meta: 'Season 1 — 第3章', file: 'STORY/s1c3.md' },
  s1c4: { title: '凍土と空',     meta: 'Season 1 — 第4章', file: 'STORY/s1c4.md' },
  s1c5: { title: '黒月の予兆',   meta: 'Season 1 — 第5章', file: 'STORY/s1c5.md' },
};

function escapeHtml(s) {
  return String(s).replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'}[c]));
}

