// 全章の outline (公開順、 公開済 + 将来予定)。 STORY_FILES (公開済) との差分で「Coming Soon teaser」 を出す
// outline.md とミラー、 章追加時はここも更新。 各 entry: { id, meta, title, icon, tagline, releaseDate?, povCharName }
// releaseDate (YYYY-MM-DD): 未公開章に設定すると teaser に「📅 YYYY/M/D 公開予定」 表示
// povCharName: 章末 scene の「次章主人公1人だけ表示」 で使う POOL の name (完全一致、 _findCharByExactName で検索)
const STORY_OUTLINE = [
  { id: 's1c1', meta: 'Season 1 — 第1章', title: '序: 七座の使命',     icon: '✨', tagline: '誰もが原虹の一筋を持つ。 世界はあなたから始まる',                       povCharName: 'ちさと' },
  { id: 's1c2', meta: 'Season 1 — 第2章', title: '南方海域の異変',     icon: '🌊', tagline: '信じる対象は、 外にあるとは限らない',                                povCharName: 'イザベル' },
  { id: 's1c3', meta: 'Season 1 — 第3章', title: '砂塵の隊商',         icon: '🐉', tagline: '血ではなく、 共に過ごした時間が家族を作る',                          povCharName: '竜爵 ヴィル' },
  { id: 's1c4', meta: 'Season 1 — 第4章', title: '凍土と空',           icon: '❄️', tagline: '強者の頂は、 孤独を共に分かち合うことで初めて温かい', releaseDate: '2026-05-02', povCharName: '龍帝 アルテミス' },
  { id: 's1c5', meta: 'Season 1 — 第5章', title: '黒月の予兆',         icon: '🌑', tagline: '銀霜の月が黒く欠ける夜、 仮面の下のもう一人の自分が、 静かに立ち上がる ─ 光と影、 二つの私の境界で', releaseDate: '2026-05-06T12:00:00+09:00', povCharName: '仮面騎士 シオン' },
  { id: 's1c6', meta: 'Season 1 — 第6章', title: '七座満つる',         icon: '🌈', tagline: '違っていても、 同じ目的を持つ仲間でいられる',                       povCharName: 'セラフィエル' },
  { id: 's1c7', meta: 'Season 1 — 第7章', title: '黒月決戦',           icon: '☄️', tagline: '影を消すのではなく、 共に在ると認める',                              povCharName: '虹意 プリズマ' },
];

// POOL から完全一致でキャラ取得 (章末「次章主人公1人だけ」 表示用、 token分解マッチを避けて Spoiler的UR覚醒後と区別)
function _findCharByExactName(name) {
  if (typeof POOL === 'undefined') return null;
  for (const tier of ['LR', 'UR', 'SSR', 'SR', 'R']) {
    const c = (POOL[tier] || []).find(x => x.name === name);
    if (c) return { ...c, tier };
  }
  return null;
}

// 最終シーン用ナビゲーション (次章公開済 / 次章未公開 Coming Soon / Season完結 の3パターン)
function buildEndNavHtml(storyId) {
  const outlineIdx = STORY_OUTLINE.findIndex(c => c.id === storyId);
  const next = (outlineIdx >= 0 && outlineIdx < STORY_OUTLINE.length - 1) ? STORY_OUTLINE[outlineIdx + 1] : null;
  const isPublished = next && STORY_FILES[next.id];
  let html = '<div class="story-end-nav">';
  if (next && isPublished) {
    // 次章公開済: そのまま遷移ボタン
    html += `<button type="button" class="story-end-nav-btn primary" onclick="openStory('${next.id}')">次の章を読む: ${escapeHtml(next.title)} <span class="story-end-nav-arrow">→</span></button>`;
  } else if (next && !isPublished) {
    // 次章未公開: Coming Soon teaser カード
    let releaseLabel = '📅 公開予定 — お楽しみに';
    if (next.releaseDate) {
      // ISO 8601 (YYYY-MM-DD or YYYY-MM-DDTHH:MM:SS+TZ) を Date でパース → YYYY/MM/DD HH:MM (時刻 00:00 なら省略)
      const d = new Date(next.releaseDate);
      if (!isNaN(d.getTime())) {
        const pad = n => String(n).padStart(2, '0');
        const dateStr = `${d.getFullYear()}/${pad(d.getMonth()+1)}/${pad(d.getDate())}`;
        const hh = d.getHours(), mm = d.getMinutes();
        const timeStr = (hh === 0 && mm === 0) ? '' : ` ${pad(hh)}:${pad(mm)}`;
        releaseLabel = `📅 <b>${dateStr}${timeStr}</b> 公開予定`;
      }
    }
    html += `<div class="story-end-nav-teaser">
      <div class="story-end-nav-teaser-badge">Coming Soon</div>
      <div class="story-end-nav-teaser-icon">${next.icon || '📖'}</div>
      <div class="story-end-nav-teaser-meta">${escapeHtml(next.meta)}</div>
      <div class="story-end-nav-teaser-title">${escapeHtml(next.title)}</div>
      ${next.tagline ? `<div class="story-end-nav-teaser-tagline">${escapeHtml(next.tagline)}</div>` : ''}
      <div class="story-end-nav-teaser-sub">${releaseLabel}</div>
    </div>`;
  } else {
    // Season完結 (outline 末尾)
    html += `<div class="story-end-nav-finale">
      <div class="story-end-nav-finale-badge">— Season 完結 —</div>
      <div class="story-end-nav-finale-sub">次の Season をお楽しみに</div>
    </div>`;
  }
  html += `<button type="button" class="story-end-nav-btn secondary" onclick="closeStory();openStoryList()">📖 ストーリー一覧へ</button>`;
  html += '</div>';
  return html;
}

// ────────────── キャラ瞬きアニメーション (Live2D風プロト) ──────────────
// 命名規則: 通常 prisma.png + 瞬き prisma_blink.png を同フォルダに配置
// 検出: <name>_blink.png が 200 OK で読めれば瞬き有効化、そうでなければ静止
// 適用範囲: ストーリーシーンの登場キャラサムネ + キャラ詳細モーダル
// 2026-05-01: 全 tier に拡張 (画像無いキャラは _blinkImageCache='ng' で skip、 副作用なし)
const BLINK_INTERVAL_MIN = 1800;   // ms (最短間隔)
const BLINK_INTERVAL_RANGE = 1700; // ms (ランダムレンジ)  → 1.8〜3.5秒
const BLINK_DURATION = 180;        // ms (目を閉じている時間)
const _blinkImageCache = new Map(); // url → 'ok' | 'ng'
let _blinkTimers = [];
function clearBlinkTimers() {
  _blinkTimers.forEach(id => clearTimeout(id));
  _blinkTimers = [];
}
function setupCharBlinkAnimations() {
  clearBlinkTimers();
  // 省電力モード or OS reduced-motion 時は瞬きOFF (発熱対策 2026-05-01)
  if (typeof _isPowerSaverActive === 'function' && _isPowerSaverActive()) return;
  // 全 tier 対象 (LR/UR/SSR/SR/R)、 _blink.png が無いキャラは _blinkImageCache='ng' で自動skip
  document.querySelectorAll('.story-char-thumb .story-char-img').forEach(imgEl => {
    const bg = imgEl.style.backgroundImage || '';
    const m = bg.match(/url\(['"]?([^'")]+)['"]?\)/);
    if (!m) return;
    const normalUrl = m[1];
    const blinkUrl = normalUrl.replace(/\.(png|jpg|jpeg|webp)(\?.*)?$/i, '_blink.$1$2');
    const cached = _blinkImageCache.get(blinkUrl);
    if (cached === 'ng') return; // 過去に存在しないと判明した
    if (cached === 'ok') { _startBlinkLoop(imgEl, normalUrl, blinkUrl); return; }
    // 初回は preload で存在確認 (404キャッシュ対策で cache buster 付与)
    const probe = new Image();
    probe.__silentFail = true;  // 期待される404 (キャラに _blink.png 未配置) を errorログから除外
    probe.onload = () => { _blinkImageCache.set(blinkUrl, 'ok'); _startBlinkLoop(imgEl, normalUrl, blinkUrl); };
    probe.onerror = () => { _blinkImageCache.set(blinkUrl, 'ng'); };
    probe.src = blinkUrl + (blinkUrl.includes('?') ? '&' : '?') + '_p=' + Date.now();
  });
}
function _startBlinkLoop(imgEl, normalUrl, blinkUrl) {
  function next() {
    // 4-7秒のランダム間隔でばらける (複数キャラが同時に瞬かないように)
    const delay = BLINK_INTERVAL_MIN + Math.random() * BLINK_INTERVAL_RANGE;
    const t1 = setTimeout(() => {
      // 要素がDOMから外れていれば停止
      if (!document.body.contains(imgEl)) return;
      imgEl.style.backgroundImage = `url('${blinkUrl}')`;
      const t2 = setTimeout(() => {
        if (!document.body.contains(imgEl)) return;
        imgEl.style.backgroundImage = `url('${normalUrl}')`;
        next();
      }, BLINK_DURATION); // 瞬きの長さ
      _blinkTimers.push(t2);
    }, delay);
    _blinkTimers.push(t1);
  }
  next();
}

// キャラ詳細モーダル用の瞬き (img.src スワップ版)
let _detailBlinkTimer = null;
function setupCharDetailBlink(c) {
  if (_detailBlinkTimer) { clearTimeout(_detailBlinkTimer); _detailBlinkTimer = null; }
  if (!c || !c.img) return;
  // 省電力モード or OS reduced-motion 時は瞬きOFF (発熱対策 2026-05-01)
  if (typeof _isPowerSaverActive === 'function' && _isPowerSaverActive()) return;
  // 全 tier 対象、 _blink.png が無いキャラは probe で skip される
  const imgEl = document.getElementById('char-detail-img');
  const zoomEl = document.getElementById('char-img-zoom-img');
  if (!imgEl) return;
  const normalUrl = c.img;
  const blinkUrl = normalUrl.replace(/\.(png|jpg|jpeg|webp)(\?.*)?$/i, '_blink.$1$2');
  const cached = _blinkImageCache.get(blinkUrl);
  if (cached === 'ng') return;
  if (cached === 'ok') { _startDetailBlinkLoop(imgEl, zoomEl, normalUrl, blinkUrl); return; }
  const probe = new Image();
  probe.__silentFail = true;  // 期待される404 (キャラに _blink.png 未配置) を errorログから除外
  probe.onload = () => { _blinkImageCache.set(blinkUrl, 'ok'); _startDetailBlinkLoop(imgEl, zoomEl, normalUrl, blinkUrl); };
  probe.onerror = () => { _blinkImageCache.set(blinkUrl, 'ng'); console.debug('[blink-detail] not found:', blinkUrl); };
  // ブラウザの404キャッシュ対策: 初回probeのみcache busterを付ける(成功後の本番swapはキャッシュ効かせる)
  probe.src = blinkUrl + (blinkUrl.includes('?') ? '&' : '?') + '_p=' + Date.now();
}
