// 画像ズームのイベント
(function bindZoom(){
  const zoom = document.getElementById('char-img-zoom');
  const img = document.getElementById('char-img-zoom-img');
  if (!zoom || !img) return;
  // 背景クリックで閉じる
  zoom.addEventListener('click', e => { if (e.target === zoom) closeImgZoom(); });
  // 画像クリックで段階ズーム
  img.addEventListener('click', onZoomImgClick);
  // ブラウザ標準の画像ドラッグ(dragstart)を完全抑止
  img.addEventListener('dragstart', e => e.preventDefault());
  // ドラッグ
  img.addEventListener('mousedown', onZoomDragStart);
  document.addEventListener('mousemove', onZoomDragMove);
  document.addEventListener('mouseup', onZoomDragEnd);
  // タッチ
  img.addEventListener('touchstart', onZoomDragStart, {passive: false});
  document.addEventListener('touchmove', onZoomDragMove, {passive: false});
  document.addEventListener('touchend', onZoomDragEnd);
  // 滑車
  zoom.addEventListener('wheel', onZoomWheel, {passive: false});
})();

document.addEventListener("keydown", e => {
  if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
  // === 最優先: ランク表モーダル (z-index 280、 全モーダル中で最上位 ===
  // result + ランク表 同時 open 時の「Esc で result 閉じてランク表残る」 バグ対策 (野沢さん指摘 2026-05-02)
  const _rtm = document.getElementById('rank-table-modal');
  if (_rtm && _rtm.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); closeRankTable(); }
    return;  // ランク表 active 中は他のキー処理 (Space/Enter 等) も全block
  }
  // 排出率詳細モーダル (ランク表と同様の最優先扱い)
  const _rdm = document.getElementById('rate-detail-modal');
  if (_rdm && _rdm.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); closeRateDetail(); }
    return;
  }
  // === 拡大画像モーダル (z-index 260、 ランク表より下) ===
  // active 中は他の Esc 処理 (story-modal の closeStory 等) を完全に通さない
  const _ciz = document.getElementById('char-img-zoom');
  if (_ciz && _ciz.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); closeImgZoom(); }
    return;
  }
  // === 最上位モーダル (1つでも開いてれば Esc で閉じる) ===
  // ようこそモーダル
  const _wm = document.getElementById('welcome-modal');
  if (_wm && _wm.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); dismissWelcomeModal(false); }
    return;
  }
  // 設定モーダル (#11)
  const _sm = document.getElementById('settings-modal');
  if (_sm && _sm.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); closeSettingsModal(); }
    return;
  }
  // アップデート通知モーダル (リロード実行モーダル)
  const _um = document.getElementById('update-modal');
  if (_um && _um.style.display && _um.style.display !== 'none') {
    if (e.key === "Escape") { e.preventDefault(); dismissUpdateModal(false); }
    return;
  }
  // アカウント案内 (account-prompt)
  const _ap = document.getElementById('account-prompt');
  if (_ap && _ap.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); if (typeof dismissAccountPrompt === 'function') dismissAccountPrompt(); }
    return;
  }
  // アカウントモーダル (signup/login フォーム)
  const _am = document.getElementById('account-modal');
  if (_am && _am.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); if (typeof closeAccountModal === 'function') closeAccountModal(); }
    return;
  }
  // 旧URL移行モーダル (legacy: pages.dev では発火しないが念のため)
  const _mm = document.getElementById('migration-modal');
  if (_mm && _mm.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); closeMigrationNotice(); }
    return;
  }
  // 要望フォーム
  const _fbm = document.getElementById('feedback-modal');
  if (_fbm && _fbm.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); closeFeedbackModal(); }
    return;
  }
  // BGMパネル
  const _bgmp = document.getElementById('bgm-panel');
  if (_bgmp && _bgmp.classList.contains('active')) {
    if (e.key === "Escape") { e.preventDefault(); closeBgmPanel(); }
    return;
  }
  // ストーリー一覧モーダル
  const _slm = document.getElementById('story-list-modal');
  if (_slm && !_slm.hasAttribute('hidden')) {
    if (e.key === "Escape") { e.preventDefault(); closeStoryList(); }
    return;
  }
  // キャラ詳細 (worldmap より優先 — 野沢さん指摘 2026-05-02 「WMからキャラ詳細出した時 Esc で キャラじゃなくWMが閉じる」)
  if ($("#char-detail").classList.contains("active")) {
    if (e.key === "Escape") {
      // 拡大中なら拡大だけ閉じる、そうでなければ詳細閉じる
      if ($("#char-img-zoom").classList.contains("active")) {
        e.preventDefault(); $("#char-img-zoom").classList.remove("active");
      } else {
        e.preventDefault(); closeCharDetail();
      }
    } else if (e.key === "ArrowLeft") {
      e.preventDefault(); navCharDetail(-1);
    } else if (e.key === "ArrowRight") {
      e.preventDefault(); navCharDetail(1);
    }
    return;
  }
  // ワールドマップモーダル (キャラ詳細より低優先)
  const _wmm = document.getElementById('world-map');
  if (_wmm && !_wmm.hasAttribute('hidden')) {
    if (e.key === "Escape") { e.preventDefault(); closeWorldMap(); }
    return;
  }
  if ($("#gallery").classList.contains("active")) {
    if (e.key === "Escape") { e.preventDefault(); closeGallery(); }
    return;
  }
  if ($("#relations").classList.contains("active")) {
    if (e.key === "Escape") { e.preventDefault(); closeRelations(); }
    return;
  }
  const _hm = $("#history-modal");
  if (_hm && _hm.classList.contains("active")) {
    if (e.key === "Escape") { e.preventDefault(); closeHistoryModal(); }
    return;
  }
  if ($("#story-modal").classList.contains("active")) {
    if (Date.now() - storyOpenedAt < STORY_KEY_GUARD_MS) return;
    const scrollEl = $("#story-scroll");
    // 目次が開いているなら Esc で目次だけ閉じる
    if ($("#story-toc").classList.contains("active")) {
      if (e.key === "Escape") { e.preventDefault(); toggleStoryToc(); return; }
    }
    if (e.key === "t" || e.key === "T") { e.preventDefault(); toggleStoryToc(); return; }
    if (e.key === "Escape") { e.preventDefault(); closeStory(); openStoryList(); }
    else if (e.key === "Enter" || e.key === "ArrowRight") {
      e.preventDefault(); storyNext();
    }
    else if (e.key === "ArrowLeft") {
      e.preventDefault(); storyPrev();
    }
    else if (e.key === " " || e.key === "ArrowDown") {
      // Space / ↓ で下スクロール (シーン送りではなく)
      e.preventDefault();
      if (scrollEl) scrollEl.scrollBy({ top: 120, behavior: 'smooth' });
    }
    else if (e.key === "ArrowUp") {
      e.preventDefault();
      if (scrollEl) scrollEl.scrollBy({ top: -120, behavior: 'smooth' });
    }
    else if (e.key === "PageDown") {
      e.preventDefault();
      if (scrollEl) scrollEl.scrollBy({ top: scrollEl.clientHeight * 0.85, behavior: 'smooth' });
    }
    else if (e.key === "PageUp") {
      e.preventDefault();
      if (scrollEl) scrollEl.scrollBy({ top: -scrollEl.clientHeight * 0.85, behavior: 'smooth' });
    }
    return;
  }
  if (stage.classList.contains("active") && (e.key === " " || e.key === "Escape")) {
    e.preventDefault(); skipRequested = true; return;
  }
  if ($("#result").classList.contains("active")) {
    if (Date.now() - resultOpenedAt < RESULT_KEY_GUARD_MS) return;
    if (e.key === "Escape") { e.preventDefault(); closeResult(); }
    else if (e.key === "Enter") {
      e.preventDefault(); closeResult();
      setTimeout(() => doTen(), 100);
    }
    return;
  }
  if (busy) return;
  // モーダル open 中は Space/Enter による裏ガチャ抑止 (野沢さん指摘 2026-05-02 Space バグ対策)
  // _isAllModalsHidden は ranking/result/char-detail/story 等 主要モーダルを網羅チェック
  if (typeof _isAllModalsHidden === 'function' && !_isAllModalsHidden()) return;
  if (e.key === " ") { e.preventDefault(); doSingle(); }
  else if (e.key === "Enter") { e.preventDefault(); doTen(); }
  else if (e.key === "g" || e.key === "G") { e.preventDefault(); openGallery(); }
});

