// F1: 共通 device id (gasshuku.js と同じ key を使う)
function getSharedDeviceId() {
  const KEY = 'prism-gasshuku-device-id';
  let id = null;
  try { id = localStorage.getItem(KEY); } catch (e) {}
  if (!id) {
    id = 'dev_' + Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
    try { localStorage.setItem(KEY, id); } catch (e) {}
  }
  return id;
}

function jstDateString(ms) {
  const d = new Date(ms);
  // JST = UTC+9
  const jstMs = d.getTime() + 9 * 3600 * 1000;
  const j = new Date(jstMs);
  const y = j.getUTCFullYear();
  const m = String(j.getUTCMonth() + 1).padStart(2, '0');
  const day = String(j.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

// F3: デバイス種別判定
function detectDeviceType() {
  try {
    const uad = navigator.userAgentData;
    if (uad && uad.mobile === true) return 'mobile';
    const ua = navigator.userAgent || '';
    if (/iPad|Tablet|PlayBook/i.test(ua)) return 'tablet';
    if (/Mobile|iPhone|Android.*Mobile|Opera Mini|IEMobile/i.test(ua)) return 'mobile';
    if (/Android/i.test(ua)) return 'tablet';
    return 'pc';
  } catch (e) { return 'unknown'; }
}
// F3: PWA standalone (ホーム画面追加 起動)
function isPWAStandalone() {
  try {
    if (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) return true;
    if (window.navigator && window.navigator.standalone === true) return true; // iOS Safari
  } catch (e) {}
  return false;
}

// F4: 流入元 (referrer + UTM) — 初回訪問時のみ取得して devices/{deviceId} に保存
function getInflowInfo() {
  try {
    const params = new URLSearchParams(window.location.search);
    return {
      referrer: document.referrer || '',
      utm: {
        source: params.get('utm_source') || '',
        medium: params.get('utm_medium') || '',
        campaign: params.get('utm_campaign') || '',
      },
      landingUrl: window.location.pathname + window.location.search,
    };
  } catch (e) { return null; }
}

// F4: エラー記録 (画像/BGM/その他、 重複抑止のため type+msg でハッシュ化、 同セッション同エラー1回まで)
const __errorLoggedKeys = new Set();
async function logErrorToFirebase(type, msg, extra) {
  if (!fbDb) return;
  // dedup キーは ?_p=... や ?v=... 等の query string を除いた形で生成
  // (cache buster 付き probe URL が unique 化して dedup を素通りする事故対策)
  const cleanMsg = String(msg || '').split('?')[0].slice(0, 100);
  const key = type + '::' + cleanMsg;
  if (__errorLoggedKeys.has(key)) return;
  __errorLoggedKeys.add(key);
  try {
    const dev = getSharedDeviceId();
    const ref = fbDb.ref('prism-gacha/_meta/eventStats/errors/' + type).push();
    await ref.set({
      ts: Date.now(),
      msg: String(msg || '').slice(0, 300),
      device: dev,
      uid: authUser ? authUser.uid : null,
      ua: (navigator.userAgent || '').slice(0, 200),
      ...(extra || {}),
    });
  } catch (e) { console.warn('[error log] failed', e); }
}

// グローバルエラーフック (window.onerror + unhandledrejection)
window.addEventListener('error', (e) => {
  // 期待される失敗 (blink probe 等で `__silentFail=true` マーカー付き) はログから除外
  if (e.target && e.target.__silentFail) return;
  // <img> のロード失敗は ev.target が IMG/AUDIO 等
  if (e.target && (e.target.tagName === 'IMG' || e.target.tagName === 'AUDIO')) {
    const src = e.target.src || '';
    logErrorToFirebase(e.target.tagName === 'IMG' ? 'imageLoadFailed' : 'audioLoadFailed', src);
    return;
  }
  if (e.message) logErrorToFirebase('jsError', e.message, { line: e.lineno, col: e.colno });
}, true);
window.addEventListener('unhandledrejection', (e) => {
  const msg = (e.reason && (e.reason.message || String(e.reason))) || 'unknown';
  logErrorToFirebase('promiseRejection', msg);
});

// F1: page load時に visit を記録 + ログイン済なら streak も更新 (F3で deviceType + isPWA + visitDates 追加、 F4で流入元)
async function logVisitAndStreak(user) {
  if (!fbDb) return;
  if (visitLogged) return;
  visitLogged = true;
  const now = Date.now();
  const todayStr = jstDateString(now);
  const dev = getSharedDeviceId();
  const deviceType = detectDeviceType();
  const isPWA = isPWAStandalone();
  try {
    // 中央 device 台帳 (ゲスト/ログイン済 共通)
    const devRef = fbDb.ref('prism-gacha/devices/' + dev);
    const devUpd = { lastVisitAt: now, deviceType, isPWA };
    if (user) devUpd.lastUid = user.uid;
    devRef.update(devUpd);
    devRef.child('firstVisitAt').transaction(c => c || now);
    devRef.child('visitDates/' + todayStr).set(now);  // F3: 30日ヒート用
    // F4: 初回訪問時のみ 流入元 (referrer + UTM) を保存
    const inflow = getInflowInfo();
    if (inflow) {
      devRef.child('referrer').transaction(c => c || inflow.referrer);
      devRef.child('utm').transaction(c => c || inflow.utm);
      devRef.child('landingUrl').transaction(c => c || inflow.landingUrl);
    }
    // 既存ゲスト/登録ユーザーの localStorage state.total を Firebase に sync (admin 表示用)
    // 過去にガチャした人も 1度起動すれば admin に数字が反映される。 transaction で Math.max なので減らない
    try {
      if (typeof state !== 'undefined' && state && typeof state.total === 'number' && state.total > 0) {
        devRef.child('totalRolls').transaction(c => Math.max(c || 0, state.total));
      }
    } catch (e) {}
  } catch (e) { console.warn('[visit] device log failed', e); }
  if (!user) return;
  // ログイン済: users[uid] にも firstVisitAt/lastVisitAt + streak + deviceType履歴 + PWA flag
  try {
    const userRef = fbDb.ref('prism-gacha/users/' + user.uid);
    const userUpd = { lastVisitAt: now };
    userRef.update(userUpd);
    userRef.child('firstVisitAt').transaction(c => c || now);
    userRef.child('deviceTypes/' + deviceType).set(true);  // 複数デバイスの累積記録
    if (isPWA) userRef.child('pwaInstalled').set(true);
    userRef.child('visitDates/' + todayStr).set(now);  // F3: 30日ヒート用
    const snap = await userRef.once('value');
    const u = snap.val() || {};
    const lastDate = u.lastLoginDate || '';
    const yesterdayStr = jstDateString(now - 86400000);
    let curStreak = u.streakCurrent || 0;
    let maxStreak = u.streakMax || 0;
    if (lastDate === todayStr) {
      if (curStreak === 0) curStreak = 1;
    } else if (lastDate === yesterdayStr) {
      curStreak = curStreak + 1;
    } else {
      curStreak = 1;
    }
    if (curStreak > maxStreak) maxStreak = curStreak;
    await userRef.update({
      lastLoginDate: todayStr,
      streakCurrent: curStreak,
      streakMax: maxStreak,
    });
  } catch (e) { console.warn('[visit] user/streak log failed', e); }
}

try {
  if (typeof firebase !== 'undefined') {
    // 名前付きインスタンスで認証セッションを他のダッシュボードから分離
    // (同じapiKey/projectでも appName 違えば localStorage keyが分離される)
    fbApp = firebase.initializeApp(FIREBASE_CONFIG, 'prism-gacha');
    fbAuth = fbApp.auth();
    fbDb = fbApp.database();
    fbAuth.onAuthStateChanged(async (user) => {
      authUser = user;
      updateAccountButton();
      if (user && !signupInProgress) { await onAuthReady(user); }
      // admin判定も並列で (失敗してもUIには影響しない)
      checkPrismAdmin();
      // F1: visit/streak 記録 (page load毎に1回)
      logVisitAndStreak(user);
      // 初回auth state確定後(login or ゲスト)にprompt表示判定
      // migration notice (旧URL限定) → account prompt の順で判定 (session flagで排他)
      if (!initialAuthCheckDone) {
        initialAuthCheckDone = true;
        setTimeout(() => {
          maybeShowMigrationNotice();
          maybeShowAccountPrompt();
          maybeShowWelcomeModal();  // ログイン済ガード内蔵
        }, 1500);
      }
    });
    // Firebase SDK が読めていない等でonAuthStateChangedが発火しなくても最終フォールバック
    setTimeout(() => {
      if (!initialAuthCheckDone) {
        initialAuthCheckDone = true;
        maybeShowMigrationNotice();
        maybeShowAccountPrompt();
        maybeShowWelcomeModal();
      }
      // F1: 万一 onAuthStateChanged が発火していなくても visit ログだけは送る (ゲスト扱い)
      if (!visitLogged) logVisitAndStreak(null);
    }, 4000);
  } else {
    // Firebase SDK未読込: それでも既存ゲストには案内(ただしFirebase動かないので案内意味ないが念のため)
    setTimeout(() => {
      maybeShowMigrationNotice();
      maybeShowAccountPrompt();
      maybeShowWelcomeModal();
    }, 2000);
  }
} catch (e) {
  console.error('Firebase init error:', e);
}

// ────────────── nickname ↔ email 変換 ──────────────
function nicknameToEmail(nickname) {
  // 日本語nicknameを Base64URL に変換して RFC5321 compliant な email にする
  const bytes = new TextEncoder().encode(nickname);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  const b64 = btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
  return 'u-' + b64 + EMAIL_DOMAIN;
}

function validateNickname(n) {
  if (!n) return 'nicknameを入力してください';
  if (n.length < 1 || n.length > 20) return '1〜20文字で入力してください';
  if (/[\x00-\x1f\x7f]/.test(n)) return '制御文字は使えません';
  if (/[@\/\\.#$\[\]]/.test(n)) return '@ . / \\ # $ [ ] は使えません';
  return null;
}

function validatePassphrase(pp) {
  if (!pp) return '合言葉を入力してください';
  if (pp.length < 4) return '合言葉は4文字以上にしてください';
  if (pp.length > 15) return '合言葉は15文字以下にしてください';
  return null;
}

// ────────────── アカウント操作 ──────────────
async function doAccountSignup() {
  const nickname = $('#signup-nickname').value.trim();
  const pp1 = $('#signup-passphrase').value;
  const pp2 = $('#signup-passphrase2').value;
  const errEl = $('#signup-error');
  errEl.textContent = '';

  const e1 = validateNickname(nickname);
  if (e1) { errEl.textContent = e1; return; }
  const e2 = validatePassphrase(pp1);
  if (e2) { errEl.textContent = e2; return; }
  if (pp1 !== pp2) { errEl.textContent = '合言葉が一致しません'; return; }

  if (!fbAuth) { errEl.textContent = 'Firebase未初期化'; return; }

  const btn = document.querySelector('#account-signup .account-submit');
  btn.disabled = true; btn.textContent = '登録中…';
  signupInProgress = true;

  try {
    // nickname重複チェック (Auth前だが未認証では読めないため、Auth後に再度チェック)
    const email = nicknameToEmail(nickname);
    const cred = await fbAuth.createUserWithEmailAndPassword(email, pp1);
    await cred.user.updateProfile({ displayName: nickname });
    await cred.user.reload();
    authUser = fbAuth.currentUser;

    // nickname重複再チェック (Auth後)
    const indexSnap = await fbDb.ref('prism-gacha/_meta/userIndex/' + nickname).once('value');
    if (indexSnap.exists() && indexSnap.val() !== cred.user.uid) {
      // 重複: Auth user を削除して中止
      try { await cred.user.delete(); } catch(e){}
      errEl.textContent = 'このnicknameは既に使われています';
      return;
    }

    // userIndex登録
    await fbDb.ref('prism-gacha/_meta/userIndex/' + nickname).set(cred.user.uid);

    // ゲスト進捗(localStorage state)を無言でcloudへ移行
    const now = Date.now();
    // F3: Welcome経由かどうか判定 (24h以内に Welcome 表示されていれば true)
    let fromWelcome = false;
    try {
      const ws = parseInt(localStorage.getItem('prism-welcome-shown-ts') || '0', 10);
      if (ws && (now - ws) < 86400000) fromWelcome = true;
    } catch (e) {}
    await fbDb.ref('prism-gacha/users/' + cred.user.uid).set({
      displayName: nickname,
      createdAt: now,
      lastLoginAt: now,
      accountCreatedFromWelcome: fromWelcome,
      state: sanitizeStateForCloud(state),
    });

    updateAccountButton();
    closeAccountModal();
    showToast('新規登録が完了しました');
  } catch (e) {
    const code = e.code || '';
    if (code.includes('email-already-in-use')) {
      errEl.textContent = 'このnicknameは既に使われています';
    } else if (code.includes('weak-password')) {
      errEl.textContent = '合言葉が弱すぎます (6文字以上推奨)';
    } else {
      errEl.textContent = e.message || '登録に失敗しました';
    }
    console.error(e);
  } finally {
    btn.disabled = false; btn.textContent = '新規登録';
    signupInProgress = false;
  }
}

async function doAccountLogin() {
  const nickname = $('#login-nickname').value.trim();
  const pp = $('#login-passphrase').value;
  const errEl = $('#login-error');
  errEl.textContent = '';

  const e1 = validateNickname(nickname);
  if (e1) { errEl.textContent = e1; return; }
  const e2 = validatePassphrase(pp);
  if (e2) { errEl.textContent = e2; return; }

  if (!fbAuth) { errEl.textContent = 'Firebase未初期化'; return; }

  const btn = document.querySelector('#account-login .account-submit');
  btn.disabled = true; btn.textContent = 'ログイン中…';

  try {
    const email = nicknameToEmail(nickname);
    await fbAuth.signInWithEmailAndPassword(email, pp);
    closeAccountModal();
    showToast('ログインしました');
  } catch (e) {
    const code = e.code || '';
    if (code.includes('user-not-found') || code.includes('wrong-password') || code.includes('invalid-credential') || code.includes('invalid-login-credentials')) {
      errEl.textContent = 'nicknameまたは合言葉が違います';
    } else {
      errEl.textContent = e.message || 'ログインに失敗しました';
    }
    console.error(e);
  } finally {
    btn.disabled = false; btn.textContent = 'ログイン';
  }
}

async function doAccountLogout() {
  try {
    await fbAuth.signOut();
    showToast('ゲストに戻りました (進捗はこのブラウザに残ります)');
    closeAccountModal();
  } catch (e) {
    console.error(e);
  }
}

// ────────────── Cloud Sync ──────────────
let cloudSyncDebounceTimer = null;
const CLOUD_SYNC_DEBOUNCE = 800;

function sanitizeStateForCloud(s) {
  return {
    total: s.total || 0,
    ur: s.ur || 0,
    pity: s.pity || 0,
    history: (Array.isArray(s.history) ? s.history : []).slice(-120),
    unlockedSet: s.unlockedSet || {},
    dupCounts: s.dupCounts || {},
    galleryViewed: s.galleryViewed || {},
    storyProgress: s.storyProgress || {},
    updatedAt: Date.now(),
  };
}

async function saveStateCloud() {
  if (!authUser || !fbDb) return;
  try {
    await fbDb.ref('prism-gacha/users/' + authUser.uid + '/state').set(sanitizeStateForCloud(state));
  } catch (e) {
    console.error('saveStateCloud error:', e);
  }
}

function scheduleCloudSync() {
  if (!authUser) return;
  if (cloudSyncDebounceTimer) clearTimeout(cloudSyncDebounceTimer);
  cloudSyncDebounceTimer = setTimeout(() => {
    saveStateCloud();
  }, CLOUD_SYNC_DEBOUNCE);
}

async function onAuthReady(user) {
  if (!fbDb) return;
  try {
    const snap = await fbDb.ref('prism-gacha/users/' + user.uid).once('value');
    const cloudData = snap.val();

    if (!cloudData) {
      // 新規ユーザー(Auth作成済だがデータ未生成): localStorage state をcloudへ送信
      await fbDb.ref('prism-gacha/users/' + user.uid).set({
        displayName: user.displayName || 'Unknown',
        createdAt: Date.now(),
        lastLoginAt: Date.now(),
        state: sanitizeStateForCloud(state),
      });
      return;
    }

    const cloudState = cloudData.state || {};
    const localHasProgress = (state.total || 0) > 0 && Object.keys(state.unlockedSet || {}).length > 0;
    const cloudTotal = cloudState.total || 0;
    const collision = localHasProgress && cloudTotal > 0 && !statesEqual(state, cloudState);

    if (collision) {
      // 差分あり → 無言で合算 (両者のmax/unionを取り、損失なし)
      const merged = mergeStates(state, cloudState);
      applyCloudState(merged);
      await saveStateCloud();
      showToast('データを最新化しました');
      try { await fbDb.ref('prism-gacha/users/' + user.uid + '/lastLoginAt').set(Date.now()); } catch (e) {}
      return;
    }

    // 衝突なし → cloud が優位 (cloudが空ならlocalを送る)
    if (cloudTotal > 0) {
      applyCloudState(cloudState);
    } else {
      await saveStateCloud();
    }

    try { await fbDb.ref('prism-gacha/users/' + user.uid + '/lastLoginAt').set(Date.now()); } catch (e) {}
  } catch (e) {
    console.error('onAuthReady error:', e);
  }
}

function statesEqual(a, b) {
  return (a.total || 0) === (b.total || 0)
    && Object.keys(a.unlockedSet || {}).length === Object.keys(b.unlockedSet || {}).length;
}

function applyCloudState(cs) {
  state.total = cs.total || 0;
  state.ur = cs.ur || 0;
  state.pity = cs.pity || 0;
  state.history = Array.isArray(cs.history) ? cs.history : [];
  state.galleryViewed = cs.galleryViewed || {};
  state.unlockedSet = cs.unlockedSet || {};
  state.dupCounts = cs.dupCounts || {};
  state.storyProgress = cs.storyProgress || {};
  localStorage.setItem("prism-gacha", JSON.stringify(state));
  updateHUD();
  if (typeof renderHistory === 'function') renderHistory();
}

function mergeStates(local, cloud) {
  const merged = {
    total: Math.max(local.total || 0, cloud.total || 0),
    ur: Math.max(local.ur || 0, cloud.ur || 0),
    pity: Math.max(local.pity || 0, cloud.pity || 0),
    history: [],
    unlockedSet: { ...(cloud.unlockedSet || {}), ...(local.unlockedSet || {}) },
    dupCounts: {},
    galleryViewed: { ...(cloud.galleryViewed || {}), ...(local.galleryViewed || {}) },
    storyProgress: {},
  };
  const allDupKeys = new Set([...Object.keys(local.dupCounts || {}), ...Object.keys(cloud.dupCounts || {})]);
  for (const k of allDupKeys) {
    merged.dupCounts[k] = Math.max((local.dupCounts && local.dupCounts[k]) || 0, (cloud.dupCounts && cloud.dupCounts[k]) || 0);
  }
  const combined = [...(cloud.history || []), ...(local.history || [])];
  merged.history = combined.slice(-120);
  const spKeys = new Set([...Object.keys(local.storyProgress || {}), ...Object.keys(cloud.storyProgress || {})]);
  for (const k of spKeys) {
    const l = (local.storyProgress && local.storyProgress[k]) || {};
    const c = (cloud.storyProgress && cloud.storyProgress[k]) || {};
    merged.storyProgress[k] = {
      lastSceneIndex: Math.max(l.lastSceneIndex || 0, c.lastSceneIndex || 0),
      totalScenes: Math.max(l.totalScenes || 0, c.totalScenes || 0),
      lastReadAt: Math.max(l.lastReadAt || 0, c.lastReadAt || 0),
      completed: !!(l.completed || c.completed),
    };
  }
  return merged;
}

// (衝突モーダル廃止: ログイン時に差分あれば自動合算→トースト表示)

// ────────────── UI handlers ──────────────
function showAccountModal() {
  const modal = $('#account-modal');
  if (!modal) return;
  if (authUser) {
    $('#account-guest-view').style.display = 'none';
    $('#account-logged-view').style.display = '';
    $('#account-info-nickname').textContent = authUser.displayName || '-';
    $('#account-info-total').textContent = state.total || 0;
    let urCount = 0, lrCount = 0;
    for (const k of Object.keys(state.unlockedSet || {})) {
      if (k.startsWith('UR_')) urCount++;
      else if (k.startsWith('LR_')) lrCount++;
    }
    // 分母は POOL から動的に取得 (キャラ追加時に分母を更新し忘れる事故を防ぐ)
    const urMax = (POOL && POOL.UR) ? POOL.UR.length : 0;
    const lrMax = (POOL && POOL.LR) ? POOL.LR.length : 0;
    $('#account-info-ur').textContent = `${urCount}/${urMax}`;
    $('#account-info-lr').textContent = `${lrCount}/${lrMax}`;
    $('#account-info-sync').textContent = authUser.metadata && authUser.metadata.lastSignInTime
      ? new Date(authUser.metadata.lastSignInTime).toLocaleString('ja-JP')
      : '-';
  } else {
    $('#account-guest-view').style.display = '';
    $('#account-logged-view').style.display = 'none';
    switchAccountTab('login');
    setTimeout(() => { const el = $('#login-nickname'); if (el) el.focus(); }, 50);
  }
  modal.classList.add('active');
}

function closeAccountModal() {
  const modal = $('#account-modal');
  if (!modal) return;
  modal.classList.remove('active');
  const le = $('#login-error'); if (le) le.textContent = '';
  const se = $('#signup-error'); if (se) se.textContent = '';
  const lp = $('#login-passphrase'); if (lp) lp.value = '';
  const sp = $('#signup-passphrase'); if (sp) sp.value = '';
  const sp2 = $('#signup-passphrase2'); if (sp2) sp2.value = '';
}

function switchAccountTab(tab) {
  document.querySelectorAll('.account-tab').forEach(el => el.classList.toggle('active', el.dataset.tab === tab));
  const login = $('#account-login'); if (login) login.style.display = tab === 'login' ? '' : 'none';
  const signup = $('#account-signup'); if (signup) signup.style.display = tab === 'signup' ? '' : 'none';
}

// (showCollisionModal / closeCollisionModal は廃止)

function updateAccountButton() {
  const label = $('#account-label');
  if (!label) return;
  label.textContent = authUser ? (authUser.displayName || 'アカウント') : 'ゲスト';
  // 詳細表記 (popup展開時のみ表示) も同期
  const labelLong = $('#account-label-long');
  if (labelLong) {
    labelLong.textContent = authUser ? `アカウント (${authUser.displayName || ''})` : 'アカウント情報';
  }
  // Admin リンクは authUser & admin判定済みの場合のみ表示
  const adminBtn = document.getElementById('btn-admin');
  if (adminBtn) {
    adminBtn.style.display = (authUser && isPrismAdmin) ? '' : 'none';
  }
  // 環境切替ボタン
  const isDevEnv = /(^|\.)dev\.prismaera\.pages\.dev$/i.test(location.host);
  const isProdEnv = location.host === 'prismaera.pages.dev';
  const envProdBtn = document.getElementById('btn-env-prod');
  const envDevBtn = document.getElementById('btn-env-dev');
  if (envProdBtn) envProdBtn.style.display = isDevEnv ? '' : 'none';
  if (envDevBtn) envDevBtn.style.display = (isProdEnv && authUser && isPrismAdmin) ? '' : 'none';
  // Home カードゲーム入口 (Phase 0 PoC) はアカウント登録者限定
  const cardgameEntry = document.getElementById('home-cardgame-card');
  if (cardgameEntry) {
    cardgameEntry.style.display = authUser ? 'flex' : 'none';
  }
}

let isPrismAdmin = false;
async function checkPrismAdmin() {
  if (!authUser || !fbDb) { isPrismAdmin = false; return; }
  try {
    const snap = await fbDb.ref('prism-gacha/_meta/admins/' + authUser.uid).once('value');
    isPrismAdmin = !!snap.val();
  } catch (e) {
    isPrismAdmin = false;
  }
  updateAccountButton();
}

// ────────────── Migration Notice (旧URL→新URL案内) ──────────────
// 通常 index.html 冒頭の redirect script が github.io アクセスを pages.dev へ自動遷移するため
// ここに到達するのはJS無効環境やredirectが何らかの理由で失敗した場合のみ
function maybeShowMigrationNotice() {
  if (!/github\.io$/i.test(location.host)) return;
  const modal = document.getElementById('migration-modal');
  if (!modal) return;
  const body = document.getElementById('migration-body');
  if (body) {
    body.innerHTML =
      '<p>Prismaera は新URL <b>prismaera.pages.dev</b> へ完全移行しました。</p>' +
      '<p>このURLは <b>2026-05-10</b> 以降、更新が止まります。引き続きお楽しみいただくには新URLへの移行をお願いします。</p>' +
      '<p>アカウント機能(ニックネーム+合言葉)を使えば、新URLでも同じ進捗で遊べます。</p>';
  }
  const actions = document.getElementById('migration-actions');
  if (actions) {
    actions.innerHTML =
      '<button class="migration-btn secondary" onclick="closeMigrationNotice()">あとで</button>' +
      '<button class="migration-btn primary" onclick="location.replace(\'https://prismaera.pages.dev/\')">新URLへ移動 →</button>';
  }
  modal.classList.add('active');
  _lockBodyScroll();
}

function closeMigrationNotice() {
  const modal = document.getElementById('migration-modal');
  if (!modal) return;
  modal.classList.remove('active');
  _unlockBodyScroll();
}

// ────────────── Account Prompt (既存ゲスト進捗ありユーザーへの案内) ──────────────
const ACCOUNT_PROMPT_KEY = 'pg_account_prompt_dismissed';

function maybeShowAccountPrompt() {
  // 以下すべて満たす場合のみ表示:
  // - 未ログイン (authUser == null)
  // - localStorage進捗あり (total > 0 かつ unlockedSet に1つ以上)
  // - 「後で」で過去に dismiss していない
  if (authUser) return;
  if (localStorage.getItem(ACCOUNT_PROMPT_KEY) === 'true') return;
  const hasProgress = (state.total || 0) > 0 && Object.keys(state.unlockedSet || {}).length > 0;
  if (!hasProgress) return;
  const modal = document.getElementById('account-prompt');
  if (!modal) return;
  modal.classList.add('active');
}

function dismissAccountPrompt() {
  localStorage.setItem(ACCOUNT_PROMPT_KEY, 'true');
  const modal = document.getElementById('account-prompt');
  if (modal) modal.classList.remove('active');
}

function acceptAccountPrompt() {
  const modal = document.getElementById('account-prompt');
  if (modal) modal.classList.remove('active');
  // アカウントモーダルの新規登録タブを開く
  showAccountModal();
  switchAccountTab('signup');
  setTimeout(() => { const el = $('#signup-nickname'); if (el) el.focus(); }, 50);
}

// 簡易トースト (他で showToast 未定義の場合のみ定義)
if (typeof window.showToast !== 'function') {
  window.showToast = function(msg) {
    let t = document.getElementById('_ptoast');
    if (!t) {
      t = document.createElement('div');
      t.id = '_ptoast';
      t.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:rgba(20,16,40,0.95);color:#fff;padding:12px 20px;border-radius:10px;font-size:14px;z-index:20000;border:1px solid rgba(200,180,255,0.3);box-shadow:0 8px 30px rgba(0,0,0,0.4);opacity:0;transition:opacity 0.3s;pointer-events:none;';
      document.body.appendChild(t);
    }
    t.textContent = msg;
    t.style.opacity = '1';
    clearTimeout(t._h);
    t._h = setTimeout(() => { t.style.opacity = '0'; }, 2800);
  };
}

// アカウントモーダルのEnter/Escape対応
document.addEventListener('keydown', e => {
  const accountModal = document.getElementById('account-modal');
  if (accountModal && accountModal.classList.contains('active')) {
    if (e.key === 'Escape') { e.stopPropagation(); e.preventDefault(); closeAccountModal(); }
    else if (e.key === 'Enter') {
      const signup = $('#account-signup');
      if (signup && signup.style.display !== 'none') { e.stopPropagation(); e.preventDefault(); doAccountSignup(); }
      else { e.stopPropagation(); e.preventDefault(); doAccountLogin(); }
    }
  }
}, true);

// account-modal の背景クリックで閉じる
document.addEventListener('DOMContentLoaded', () => {
  const am = document.getElementById('account-modal');
  if (am) am.addEventListener('click', e => { if (e.target === am) closeAccountModal(); });
  // D 案: 起動直後に R/SR サムネを background prefetch (新規ユーザーの初回ガチャ画像読み込み対策、 即実行)
  _prefetchLowTierThumbs();
  // 起動から少し経った後に 公開済章の全ガチャキャラ画像を自動事前ダウンロード (24h cooldown)
  // 起動から 5秒待ってから precache 開始 (UI 描画 + 初期 layout 完了後、 野沢さん指摘 2026-05-03 電池消費改善)
  setTimeout(() => { _autoPrecacheGachaImages().catch(() => {}); }, 5000);
});

// ============================================================
// ガチャ画像 prefetch / preload (D 案: 起動時 R/SR + 高tier on-demand)
// ============================================================
let _lowTierPrefetched = false;
function _prefetchLowTierThumbs() {
  if (_lowTierPrefetched) return;
  if (typeof POOL === 'undefined') return;
  _lowTierPrefetched = true;
  // R + SR の _thumb.webp + .png を低優先度 background fetch (sw.js が傍受してキャッシュ)
  // 約90-100枚 / 5-8MB 想定、 1回のみ実行 (idempotent)
  const urls = new Set();
  for (const tier of ['R', 'SR']) {
    (POOL[tier] || []).forEach(c => {
      if (!c || !c.img) return;
      urls.add(c.img);
      urls.add(toThumbUrl(c.img));
    });
  }
  console.log(`[prefetch] R/SR thumbs: ${urls.size} URLs`);
  for (const url of urls) {
    try { fetch(url, { credentials: 'omit', priority: 'low' }).catch(() => {}); } catch (e) {}
  }
}

// ============================================================
// 起動時 自動事前ダウンロード (公開済章のガチャ排出キャラ画像)
// 段階1: thumb (オーバーレイ表示) → 段階2: full PNG (バックグラウンド)
// 24h以内に走った後はスキップ (localStorage で cooldown 管理)
// 「スキップ」 ボタンで即中断可能、 ガチャ時の on-demand preload にフォールバック
// ============================================================
let _autoPrecacheSkipped = false;
let _autoPrecacheRunning = false;
function _skipAutoPrecache() {
  _autoPrecacheSkipped = true;
  const ov = document.getElementById('auto-precache-overlay');
  if (ov) ov.hidden = true;
  // スキップ時は cooldown を記録しない (次回起動時に再試行)
}
function _isChapterReleased(chapterId) {
  if (typeof STORY_FILES === 'undefined' || !STORY_FILES[chapterId]) return false;
  if (typeof STORY_OUTLINE === 'undefined') return true;
  const o = STORY_OUTLINE.find(x => x && x.id === chapterId);
  if (o && o.releaseDate) {
    const ts = new Date(o.releaseDate).getTime();
    if (!isNaN(ts) && ts > Date.now()) return false;
  }
  return true;
}
// 公開予定日の表示用フォーマット (M/D HH:MM、 ゼロ埋め2桁)
function _formatReleaseDate(chapterId) {
  if (typeof STORY_OUTLINE === 'undefined') return '近日';
  const o = STORY_OUTLINE.find(x => x && x.id === chapterId);
  if (!o || !o.releaseDate) return '近日';
  const d = new Date(o.releaseDate);
  if (isNaN(d.getTime())) return '近日';
  const pad = n => String(n).padStart(2, '0');
  // 時刻部分が 00:00 の場合は日付のみ、 そうでなければ日付+時刻
  const hh = d.getHours(), mm = d.getMinutes();
  const datePart = `${pad(d.getMonth() + 1)}/${pad(d.getDate())}`;
  if (hh === 0 && mm === 0) return datePart;
  return `${datePart} ${pad(hh)}:${pad(mm)}`;
}
// グローバル info toast (公開予定告知 等、 WM外でも表示可能)
let _infoToastTimer = null;
function _showInfoToast(text, durationMs) {
  let toast = document.getElementById('info-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'info-toast';
    toast.className = 'info-toast';
    document.body.appendChild(toast);
  }
  toast.textContent = text;
  toast.classList.add('show');
  if (_infoToastTimer) clearTimeout(_infoToastTimer);
  _infoToastTimer = setTimeout(() => { toast.classList.remove('show'); }, durationMs || 2200);
}
async function _autoPrecacheGachaImages() {
  if (_autoPrecacheRunning) return;
  if (typeof POOL === 'undefined') return;
  // 容量節約モードユーザーは skip (cellular でも自動DL したくない場合のため)
  if (navigator.connection && navigator.connection.saveData) {
    console.log('[auto-precache] save-data mode, skip');
    return;
  }
  _autoPrecacheRunning = true;
  // 公開済章のキャラだけ集計 (releaseDate <= now かつ STORY_FILES に登録済)
  const thumbUrls = [];
  const fullUrls = [];
  for (const tier of ['LR', 'UR', 'SSR', 'SR', 'R']) {
    (POOL[tier] || []).forEach(c => {
      if (!c || !c.img || !c.chapter) return;
      if (!_isChapterReleased(c.chapter)) return;
      fullUrls.push(c.img);
      thumbUrls.push(toThumbUrl(c.img));
    });
  }
  if (thumbUrls.length === 0) { _autoPrecacheRunning = false; return; }
  // 事前 cache check: 全部キャッシュ済ならオーバーレイ表示せず即終了 (リロード時の高速復帰)
  const allUrls = [...thumbUrls, ...fullUrls];
  let missingThumbs = thumbUrls.length;
  let missingFulls = fullUrls.length;
  try {
    // ignoreSearch:true で cache buster 差異を無視 (野沢さん指摘 2026-05-03 「Ver変わるたび全DL害悪」)
    // 同 path のキャッシュがあれば skip = 再DL しない
    const thumbCached = await Promise.all(thumbUrls.map(u => caches.match(u, { ignoreSearch: true }).then(r => !!r).catch(() => false)));
    const fullCached = await Promise.all(fullUrls.map(u => caches.match(u, { ignoreSearch: true }).then(r => !!r).catch(() => false)));
    missingThumbs = thumbCached.filter(c => !c).length;
    missingFulls = fullCached.filter(c => !c).length;
  } catch (e) {
    console.warn('[auto-precache] cache check failed', e);
  }
  console.log(`[auto-precache] missing thumb=${missingThumbs}/${thumbUrls.length}, full=${missingFulls}/${fullUrls.length}`);
  if (missingThumbs === 0 && missingFulls === 0) {
    // 全 cache 済 → オーバーレイなしで即進行
    _autoPrecacheRunning = false;
    return;
  }
  const ov = document.getElementById('auto-precache-overlay');
  const fillEl = ov && ov.querySelector('.auto-precache-fill');
  const textEl = ov && ov.querySelector('.auto-precache-text');
  const subEl = ov && ov.querySelector('.auto-precache-sub');
  // 段階1: thumb 未DL あれば オーバーレイ表示 + DL
  if (missingThumbs > 0) {
    if (subEl) subEl.textContent = `スムーズに遊べるよう、 公開済キャラの画像 ${missingThumbs}件を読み込みます`;
    if (ov) ov.hidden = false;
    try {
      await _downloadAllAssets((done, total) => {
        if (_autoPrecacheSkipped) return;
        const pct = total ? Math.round(done / total * 100) : 0;
        if (fillEl) fillEl.style.width = pct + '%';
        if (textEl) textEl.textContent = `${done} / ${total} (${pct}%)`;
      }, thumbUrls);
    } catch (e) { console.warn('[auto-precache] thumb DL error', e); }
    if (ov) ov.hidden = true;
  }
  // 段階2: full PNG 未DL あれば バックグラウンドで DL (オーバーレイなし)
  if (missingFulls > 0 && !_autoPrecacheSkipped) {
    setTimeout(async () => {
      try {
        await _downloadAllAssets(null, fullUrls);
      } catch (e) { console.warn('[auto-precache] full DL error', e); }
    }, 1500);
  }
  _autoPrecacheRunning = false;
}

// 高tier (SSR/UR/LR) ヒット時に演出開始前にキャラ画像を preload + 短時間待機
// timeout 内に load 完了したら即 resolve、 超えたら諦めて続行 (演出継続を妨げない)
function _preloadCharImagesWithTimeout(result, timeoutMs) {
  return new Promise((resolve) => {
    if (!result) return resolve();
    // result が単発 (object) と 10連 (array) の両方ありうる
    const items = Array.isArray(result) ? result : [result];
    const urls = new Set();
    items.forEach(c => {
      if (c && c.img) {
        urls.add(c.img);
        urls.add(toThumbUrl(c.img));
      }
    });
    if (urls.size === 0) return resolve();
    let pending = urls.size;
    let done = false;
    const finish = () => { if (!done) { done = true; resolve(); } };
    const onAny = () => { pending -= 1; if (pending <= 0) finish(); };
    for (const url of urls) {
      const img = new Image();
      img.onload = onAny;
      img.onerror = onAny;
      img.src = url;
    }
    setTimeout(finish, timeoutMs);  // タイムアウトで強制 resolve (演出を待たせすぎない)
  });
}

// ============================================================
// バージョン通知: version.json と localStorage を比較して
// 差分があれば更新モーダルを表示 (初回アクセスは通知スキップ)
// ============================================================
const PRISMAERA_VERSION_LS_KEY = 'prismaera-last-seen-version';
let _prismaeraChangelogCache = null;
let _prismaeraTargetVersion = null;

async function checkPrismaeraVersion() {
  try {
    const res = await fetch('version.json?t=' + Date.now(), { cache: 'no-store' });
    if (!res.ok) return;
    const data = await res.json();
    const currentVer = data.version;
    const changelog = Array.isArray(data.changelog) ? data.changelog : [];
    _prismaeraChangelogCache = changelog;

    // ヘッダーのバージョン表記を version.json で上書き
    // dev 環境では cache buster 末尾の文字 (a/b/c...) を suffix として表示 (確認用)
    const verEl = document.getElementById('app-version');
    if (verEl) {
      let suffix = '';
      const isDevHost = location.hostname.startsWith('dev.') || location.hostname.includes('localhost');
      if (isDevHost) {
        try {
          // [a-z]+ で複数文字 suffix (z 到達後の aa, bb, cc... も対応)
          const cb = (document.querySelector('link[rel=stylesheet]')?.href || '').match(/\?v=\d{8}([a-z]+)/);
          if (cb) suffix = cb[1];
        } catch (e) {}
      }
      verEl.textContent = `v${currentVer}${suffix}`;
    }

    let lastSeen = null;
    try { lastSeen = localStorage.getItem(PRISMAERA_VERSION_LS_KEY); } catch (e) {}

    // 初回アクセスは通知せず現バージョンを保存 (スパム防止)
    if (!lastSeen) {
      try { localStorage.setItem(PRISMAERA_VERSION_LS_KEY, currentVer); } catch (e) {}
      return;
    }
    if (lastSeen === currentVer) return;

    showPrismaeraUpdateModal(lastSeen, currentVer, changelog);
  } catch (e) {
    console.warn('[prismaera] version check failed', e);
  }
}

function showPrismaeraUpdateModal(fromVer, toVer, changelog) {
  const modal = document.getElementById('update-modal');
  if (!modal) return;

  _prismaeraTargetVersion = toVer;

  const fromEl = document.getElementById('update-from');
  const toEl = document.getElementById('update-to');
  if (fromEl) fromEl.textContent = 'v' + fromVer;
  if (toEl) toEl.textContent = 'v' + toVer;

  const notesUl = document.getElementById('update-notes');
  if (notesUl) {
    notesUl.innerHTML = '';
    const latest = changelog.find(c => c && c.version === toVer) || changelog[0];
    const notes = latest && Array.isArray(latest.notes) ? latest.notes : [];
    notes.forEach(n => {
      const li = document.createElement('li');
      li.textContent = n;
      notesUl.appendChild(li);
    });
  }

  const histEl = document.getElementById('update-history');
  if (histEl) {
    histEl.innerHTML = '';
    histEl.style.display = 'none';
    changelog.forEach(entry => {
      if (!entry) return;
      const section = document.createElement('details');
      section.className = 'update-history-entry';
      const h = document.createElement('summary');
      h.className = 'update-history-head';
      h.textContent = 'v' + entry.version + ' (' + (entry.date || '') + ')';
      section.appendChild(h);
      const ul = document.createElement('ul');
      (entry.notes || []).forEach(n => {
        const li = document.createElement('li');
        li.textContent = n;
        ul.appendChild(li);
      });
      section.appendChild(ul);
      histEl.appendChild(section);
    });
  }

  modal.style.display = 'flex';
  _lockBodyScroll();
}

function dismissUpdateModal(reload) {
  const modal = document.getElementById('update-modal');
  if (!modal) return;
  const isHistoryOnly = modal.classList.contains('history-only');
  try {
    if (_prismaeraTargetVersion) {
      localStorage.setItem(PRISMAERA_VERSION_LS_KEY, _prismaeraTargetVersion);
    }
  } catch (e) {}
  modal.style.display = 'none';
  _unlockBodyScroll();
  // 履歴閲覧モードの後始末 (タイトル戻し + クラス除去、 reload もしない)
  if (isHistoryOnly) {
    modal.classList.remove('history-only');
    const titleEl = modal.querySelector('.update-title');
    if (titleEl) titleEl.textContent = '新しいバージョンが届きました';
    const histEl = document.getElementById('update-history');
    if (histEl) histEl.style.display = 'none';
    return;
  }
  if (reload) {
    // PWA/ServiceWorkerキャッシュ破棄目的で location.reload(true)
    // (引数は新ブラウザで非対応でも location.reload() に fallback)
    try { location.reload(true); } catch (e) { location.reload(); }
  }
}

// 設定モーダルからアップデート履歴を任意タイミングで開く (2026-05-01)
// update-modal を再利用するが「履歴閲覧モード」 として version 比較・閉じる時の reload を行わない
function openVersionHistoryModal() {
  const modal = document.getElementById('update-modal');
  if (!modal) return;
  // 履歴データ取得 (起動時に既に fetch 済みでなければ非同期取得)
  const renderWith = (changelog) => {
    if (!Array.isArray(changelog)) changelog = [];
    // history-only モードフラグ (closeUpdateModal で reload しないため)
    modal.classList.add('history-only');
    _prismaeraTargetVersion = null;
    // タイトル差し替え + version 表示・notes 非表示は CSS 側で対応
    const titleEl = modal.querySelector('.update-title');
    if (titleEl) titleEl.textContent = '📜 アップデート履歴';
    const histEl = document.getElementById('update-history');
    if (histEl) {
      histEl.innerHTML = '';
      changelog.forEach(entry => {
        if (!entry) return;
        const section = document.createElement('details');
        section.className = 'update-history-entry';
        const h = document.createElement('summary');
        h.className = 'update-history-head';
        h.textContent = 'v' + entry.version + ' (' + (entry.date || '') + ')';
        section.appendChild(h);
        const ul = document.createElement('ul');
        (entry.notes || []).forEach(n => {
          const li = document.createElement('li');
          li.textContent = n;
          ul.appendChild(li);
        });
        section.appendChild(ul);
        histEl.appendChild(section);
      });
      histEl.style.display = 'block';
    }
    modal.style.display = 'flex';
    _lockBodyScroll();
  };
  // version.json をその場で取得 (cache buster なし、 軽量)
  fetch('/version.json?_t=' + Date.now())
    .then(r => r.ok ? r.json() : null)
    .then(j => renderWith(j && Array.isArray(j.changelog) ? j.changelog : []))
    .catch(() => renderWith([]));
}

function toggleUpdateHistory() {
  const hist = document.getElementById('update-history');
  if (!hist) return;
  hist.style.display = (hist.style.display === 'none') ? 'block' : 'none';
}

// 起動時に version.json をチェック
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', checkPrismaeraVersion);
} else {
  checkPrismaeraVersion();
}

// ====== #11 設定モーダル ======
const SETTINGS_KEY = 'prism-settings';
function loadSettings() {
  try { return JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}') || {}; }
  catch { return {}; }
}
function saveSettings(s) {
  try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(s)); } catch {}
  applySettings(s);
}
function applySettings(s) {
  // 文字サイズ (大/中/小)
  const root = document.documentElement;
  root.dataset.fontsize = s.fontSize || 'medium';
  // 省電力モード (発熱対策 2026-05-01) — アンビエントアニメ + blur 停止
  document.body.classList.toggle('power-saver', !!s.powerSaver);
}
// OS reduced-motion または ユーザー省電力モード ON 時 true
function _isPowerSaverActive() {
  try {
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return true;
  } catch {}
  try {
    const s = JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}');
    return !!s.powerSaver;
  } catch { return false; }
}
